class Component extends DCLogic {
  state = (() => { let page = 'home'; try { page = localStorage.getItem('fu4_page') || 'home'; } catch(e){} let theme = 'system'; try { theme = localStorage.getItem('fu_theme') || 'system'; } catch(e){}
    return { page, theme, cw:1280, menuOpen:false, tab:'test', f:{ url:'', goal:'', success:'', access:'public' }, step:6, vstate: this.props.verdict || 'stuck', open:-1, copied:-1, fb:{}, howOpen:false, faq:-1, briefTab:'product', journeys: JOURNEYS.map(j => ({...j})), linkCopied:false, hstep:0 }; })();
  get rm(){ return (window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches) || this.props.motion === false; }
  get isDark(){ const t = this.state.theme; return t === 'dark' || (t === 'system' && window.matchMedia && matchMedia('(prefers-color-scheme: dark)').matches); }
  applyTheme(){ const r = document.documentElement, t = this.state.theme; if (t === 'system') r.removeAttribute('data-fu-theme'); else r.setAttribute('data-fu-theme', t); try { localStorage.setItem('fu_theme', t); } catch(e){} }
  componentDidMount(){
    this.applyTheme();
    this.revealLines(); this.startHero(); setTimeout(() => this.scanReveal(), 50);
    if (this.props.screen) this.applyScreen(this.props.screen);
    else if (this.state.page === 'run') this.startRun();
    this.onDoc = e => { if (this.state.menuOpen && this.barEl && !this.barEl.contains(e.target)) this.setState({ menuOpen:false }); };
    document.addEventListener('click', this.onDoc);
  }
  startHero(){ clearInterval(this.t1); if (this.rm) { this.setState({ hstep:6 }); return; } this.t1 = setInterval(() => this.setState(s => ({ hstep:(s.hstep+1) % HRUN.length })), 2000); }
  revealLines(){ if (this.rm) return; (this.lines||[]).filter(e => e.isConnected).forEach((el,i) => el.animate && el.animate([{transform:'translateY(105%)'},{transform:'none'}], {duration:900, delay:120 + i*90, easing:'cubic-bezier(.16,1,.3,1)', fill:'backwards'})); }
  countUp(el){ const to = +el.dataset.count, from = el.dataset.from != null ? +el.dataset.from : 0, suf = el.dataset.suf || '', t0 = performance.now(), d = 1200; const tick = now => { const p = Math.min(1, (now - t0) / d), e = 1 - Math.pow(1 - p, 3); el.textContent = Math.round(from + (to - from) * e) + suf; if (p < 1) requestAnimationFrame(tick); }; requestAnimationFrame(tick); }
  onHeader(){ const b = this.barEl, p = this.progEl; if (!b) return; const y = window.scrollY, on = y > 24;
    if (on !== this.hdrOn) { this.hdrOn = on; b.style.background = on ? 'color-mix(in srgb, var(--bg) 78%, transparent)' : 'transparent'; b.style.borderColor = on ? 'var(--line)' : 'transparent'; b.style.boxShadow = on ? '0 12px 32px rgba(0,0,0,.16)' : 'none'; b.style.backdropFilter = b.style.webkitBackdropFilter = on ? 'blur(16px) saturate(1.4)' : 'none'; }
    if (p) { const h = document.documentElement.scrollHeight - window.innerHeight; p.style.transform = 'scaleX(' + (h > 0 ? Math.min(1, y / h) : 0) + ')'; } }
