"use client";

import { useRouter } from "next/navigation";
import { useState, type FormEvent } from "react";

import type { ApiError } from "@/lib/types";

type Access = "public" | "link" | "account" | "signup";

const ACCESS_OPTIONS: { value: Access; label: string; help: string }[] = [
  { value: "public", label: "No login", help: "Look at what is public. This is the default." },
  { value: "link", label: "I have a demo or guest link", help: "The visit begins at a page that is already past the login." },
  { value: "account", label: "Use a test account", help: "Sign in with a throwaway email and password you give." },
  { value: "signup", label: "Let it sign up by itself", help: "The visitor makes up a test account on your signup form." },
];

type FormError = {
  field: "url" | "startUrl" | "credentials" | "permission" | "success" | "form";
  title?: string;
  message: string;
};

const TITLES: Record<string, string> = {
  queue_full: "The queue is full",
  rate_limited: "You've reached the hourly limit",
  server_error: "Something went wrong",
};

// What the form starts with: empty, or filled from a suggested journey on a product brief.
export type RunFormInitial = { url: string; goal: string; success: string; brief: string };

export function RunForm({ initial }: { initial?: RunFormInitial }) {
  const router = useRouter();
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<FormError | null>(null);
  const [access, setAccess] = useState<Access>("public");

  async function onSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const form = new FormData(event.currentTarget);
    const url = String(form.get("url") ?? "").trim();
    const goal = String(form.get("goal") ?? "").trim();
    const permission = form.get("permission") === "on";
    const successCondition = String(form.get("successCondition") ?? "").trim();
    // Only the fields of the chosen option exist in the form, so nothing else is read or sent.
    const startUrl = access === "link" ? String(form.get("startUrl") ?? "").trim() : "";
    const testEmail = access === "account" ? String(form.get("testEmail") ?? "").trim() : "";
    const testPassword = access === "account" ? String(form.get("testPassword") ?? "") : "";

    if (!url) return setError({ field: "url", message: "Enter your app's address." });
    if (!permission) {
      return setError({ field: "permission", message: "Please confirm you're allowed to test this app." });
    }

    if (access === "link" && !startUrl) {
      return setError({ field: "startUrl", message: "Enter the demo or guest link, or choose another option." });
    }
    if (access === "account" && (!testEmail || !testPassword)) {
      return setError({
        field: "credentials",
        message: "Enter both a test email and a test password, or choose another option.",
      });
    }

    setSubmitting(true);
    setError(null);
    try {
      const response = await fetch("/api/runs", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          url,
          goal,
          briefId: initial?.brief || undefined,
          permission,
          successCondition: successCondition || undefined,
          access,
          startUrl: startUrl || undefined,
          testEmail: testEmail || undefined,
          testPassword: testPassword || undefined,
        }),
      });
      const body = (await response.json().catch(() => null)) as { id?: string } | ApiError | null;
      if (response.ok && body && "id" in body && body.id) {
        router.push(`/run/${body.id}`);
        return;
      }
      const apiError = body && "error" in body ? body : null;
      const code = apiError?.error ?? "server_error";
      setError({
        field:
          code === "invalid_url"
            ? "url"
            : code === "success_too_long"
              ? "success"
            : code === "invalid_start_url"
              ? "startUrl"
              : code === "invalid_credentials"
                ? "credentials"
                : code === "permission_required"
                  ? "permission"
                  : "form",
        title: TITLES[code],
        message: apiError?.message ?? "Something went wrong on our side. Please try again in a minute.",
      });
    } catch {
      setError({ field: "form", title: "Couldn't reach the server", message: "Check your connection and try again." });
    }
    setSubmitting(false);
  }

  const inputClass =
    "mt-2 block w-full rounded-lg border border-line bg-surface px-3.5 py-3 text-base text-foreground " +
    "placeholder:text-subtle focus:border-accent focus:outline-none focus:ring-2 focus:ring-accent/30";

  return (
    <form onSubmit={onSubmit} noValidate className="space-y-6">
      <div>
        <label htmlFor="url" className="font-medium">
          Your app&apos;s address
        </label>
        <input
          id="url"
          name="url"
          type="url"
          inputMode="url"
          autoComplete="url"
          placeholder="https://yourapp.com"
          defaultValue={initial?.url}
          required
          aria-invalid={error?.field === "url"}
          aria-describedby={error?.field === "url" ? "url-error" : undefined}
          className={inputClass}
        />
        {error?.field === "url" && (
          <p id="url-error" className="mt-2 text-sm text-danger">
            {error.message}
          </p>
        )}
      </div>

      <div>
        <label htmlFor="goal" className="font-medium">
          What should they try to do? <span className="font-normal text-subtle">(optional)</span>
        </label>
        <textarea
          id="goal"
          name="goal"
          rows={2}
          maxLength={500}
          placeholder="For example: sign up and create your first project"
          defaultValue={initial?.goal}
          aria-describedby="goal-hint"
          className={inputClass}
        />
        <p id="goal-hint" className="mt-2 text-sm text-subtle">
          Leave this empty and they&apos;ll work out what the product does and try its main feature.
        </p>
      </div>

      <div>
        <label htmlFor="successCondition" className="font-medium">
          What does success look like? <span className="font-normal text-subtle">(optional)</span>
        </label>
        <input
          id="successCondition"
          name="successCondition"
          type="text"
          maxLength={300}
          placeholder="For example: a project appears in the dashboard"
          defaultValue={initial?.success}
          aria-describedby="success-hint"
          className={inputClass}
        />
        <p id="success-hint" className="mt-2 text-sm text-subtle">
          The check at the end judges this, not only the wording of the goal. Leave it empty and the goal is checked
          as worded.
        </p>
        {error?.field === "success" && <p className="mt-2 text-sm text-danger">{error.message}</p>}
      </div>

      <fieldset className="space-y-3" aria-describedby="access-hint">
        <legend className="font-medium">How should the visitor get in?</legend>
        <p id="access-hint" className="text-sm text-subtle">
          Apps that only offer Google or GitHub login: use a demo or guest link.
        </p>
        <div className="space-y-2">
          {ACCESS_OPTIONS.map((option) => (
            <label
              key={option.value}
              className={
                "flex cursor-pointer items-start gap-3 rounded-xl border p-4 " +
                (access === option.value ? "border-accent bg-surface" : "border-line bg-surface hover:border-accent/60")
              }
            >
              <input
                type="radio"
                name="access"
                value={option.value}
                checked={access === option.value}
                onChange={() => setAccess(option.value)}
                className="mt-1 size-5 shrink-0 accent-accent"
              />
              <span>
                <span className="block font-medium">{option.label}</span>
                <span className="mt-0.5 block text-sm text-muted">{option.help}</span>
              </span>
            </label>
          ))}
        </div>

        {access === "link" && (
          <div className="rounded-xl border border-line bg-surface p-4">
            <label htmlFor="startUrl" className="font-medium">
              Start link
            </label>
            <input
              id="startUrl"
              name="startUrl"
              type="url"
              inputMode="url"
              placeholder="https://yourapp.com/demo"
              aria-invalid={error?.field === "startUrl"}
              aria-describedby="startUrl-hint"
              className={inputClass}
            />
            <p id="startUrl-hint" className="mt-2 text-sm text-subtle">
              A demo page, guest mode or preview build that is already past the login. The visit begins here.
            </p>
            {error?.field === "startUrl" && <p className="mt-2 text-sm text-danger">{error.message}</p>}
          </div>
        )}

        {access === "account" && (
          <div className="space-y-4 rounded-xl border border-line bg-surface p-4">
            <p className="rounded-lg border border-warning/30 bg-warning-soft p-3 text-sm">
              Use a throwaway account. Kept only for this run, never shown to the AI, deleted when the run ends.
            </p>
            <div>
              <label htmlFor="testEmail" className="text-sm font-medium">
                Test email
              </label>
              <input
                id="testEmail"
                name="testEmail"
                type="email"
                autoComplete="off"
                placeholder="test@yourapp.com"
                aria-invalid={error?.field === "credentials"}
                className={inputClass}
              />
            </div>
            <div>
              <label htmlFor="testPassword" className="text-sm font-medium">
                Test password
              </label>
              <input
                id="testPassword"
                name="testPassword"
                type="password"
                autoComplete="new-password"
                aria-invalid={error?.field === "credentials"}
                className={inputClass}
              />
            </div>
            {error?.field === "credentials" && <p className="text-sm text-danger">{error.message}</p>}
          </div>
        )}

        {access === "signup" && (
          <p className="rounded-xl border border-line bg-surface p-4 text-sm text-muted">
            Works for email-and-password signup without email verification.
          </p>
        )}
      </fieldset>

      <div>
        <label className="flex items-start gap-3">
          <input
            name="permission"
            type="checkbox"
            required
            aria-invalid={error?.field === "permission"}
            className="mt-1 size-5 shrink-0 accent-accent"
          />
          <span>This is my app or I have permission to test it</span>
        </label>
        {error?.field === "permission" && <p className="mt-2 text-sm text-danger">{error.message}</p>}
      </div>

      {error?.field === "form" && (
        <div role="alert" className="rounded-lg border border-danger/30 bg-danger-soft p-4 text-sm">
          {error.title && <p className="font-medium text-danger">{error.title}</p>}
          <p className="mt-1 text-foreground">{error.message}</p>
        </div>
      )}

      <button
        type="submit"
        disabled={submitting}
        className="w-full rounded-lg bg-accent px-5 py-3 font-medium text-white hover:bg-accent-strong focus:outline-none focus-visible:ring-2 focus-visible:ring-accent/40 focus-visible:ring-offset-2 disabled:opacity-60 sm:w-auto dark:text-background"
      >
        {submitting ? "Starting…" : "Start the visit"}
      </button>
    </form>
  );
}
// Shapes returned by GET /api/runs/[id]. Shared by the API route and the run page.

export type RunStatus = "queued" | "running" | "done" | "failed";
export type Outcome =
  | "achieved"
  | "achieved_unconfirmed"
  | "not_achieved"
  | "unverified"
  | "gave_up"
  | "blocked"
  | "max_steps"
  | "error";

export type Clarity = "yes" | "partly" | "no";

// How the founder chose to let the visitor in (the form's "How should the visitor get in?").
export type AccessMode = "public" | "link" | "account" | "signup";

// What a newcomer sees on the landing page without logging in (written by the worker).
export type FirstImpression = {
  what_it_does: { clear: Clarity; summary: string };
  who_its_for: { clear: Clarity; summary: string };
  main_action: { obvious: Clarity; summary: string };
  hesitations: string[];
  suggestions: string[];
};

// What happened after the visitor submitted a login or sign-up form (worker/login_diagnosis.py).
export type LoginDiagnosis = {
  stage: "sign_in" | "sign_up";
  result: "signed_in" | "rejected" | "needs_verification" | "no_effect";
  challenge: "email_verification" | "captcha" | "two_factor" | null;
  page_message: string | null;
  http_statuses: string[];
  step: number | null;
  url: string | null;
  detail?: string;
};

// Which way in the visit used. Never holds a credential: the test login's values are not stored here.
export type Entry = {
  start_link: string | null;
  access_mode?: AccessMode;
  // A login written on the page itself (a demo login for visitors), typed with the page's own values.
  page_login?: "not_used" | "shown_on_page" | "typed";
  // That login was accepted: the password field went away and the visit moved on. Absent on older runs.
  page_login_worked?: boolean;
  diagnosis?: LoginDiagnosis | null;
  // The site showed a bot check ("Verify you are human"); the visit did not try to get past it.
  bot_check?: { phrase: string; url: string; title: string; step: number } | null;
  test_login: "not_provided" | "provided_not_used" | "used" | "failed";
  self_signup: "not_used" | "used" | "blocked_verification" | "blocked_third_party" | "failed";
  third_party_options: string[];
  created_account_email: string | null;
  blocked_at_login: boolean;
};

// One ranked problem from the report writer (worker/report_writer.py). Every one points at a real step.
export type Finding = {
  title: string;
  severity: "high" | "medium" | "low";
  kind: "site_problem" | "unclear_wording" | "hidden_error";
  expected: string;
  happened: string;
  evidence: {
    step: number;
    url: string | null;
    screenshot_url: string | null;
    page_errors: string[];
    quote: string | null;
  };
  reproduce: string[];
  fix_prompt: string;
  // Steps of the problems the visitor noted that this finding covers, so they are not listed twice.
  covers_steps?: number[];
  // The problem is observed in the run; the fix is our recommendation. Absent on older findings.
  basis?: "observed";
  fix_basis?: "recommendation";
  // Three to five checks a person can make by looking at the page after the change.
  acceptance_criteria?: string[];
  // The same symptom seen again, merged into this finding: the earliest step is `evidence`, these are the rest.
  also_seen_at?: { step: number; url: string | null; screenshot_url: string | null; page_errors: string[] }[];
};

// What a statement in the report rests on: the run record, the independent check, or our suggestion.
export type Basis = "observed" | "verified" | "recommendation";

export type VerdictKind = "got_through" | "unconfirmed" | "stuck" | "login_wall" | "bot_check" | "our_failure";

// One verdict per run (worker/verdict.py).
export type Verdict = {
  kind: VerdictKind;
  headline: string;
  where_step: number | null;
  where_url: string | null;
  evidence_quote: string;
  basis: "observed" | "verified";
  detail?: string;
  ways_in?: string[];
};

// How the report was made (worker/run_facts.py): counted from the run, not written by a model.
export type RunFacts = {
  steps_taken: number;
  recoveries: { step: number; rung: string; how: string; instruction: string }[];
  own_issues: { step: number | null; instruction: string; reason: string | null }[];
  page_reloads: number;
  page_errors: string[];
  page_error_count: number;
  verifier: { verdict: string | null; quote: string } | null;
  success_condition: string | null;
  checked_without_success_condition: boolean;
  cost_usd: number;
  duration_seconds: number;
  agent_version?: string;
  worker_id?: string;
  trace_id?: string | null;
};

// Check again (worker/retest.py): what happened to each finding of the original run.
export type RetestLabel = "fixed" | "still_present" | "not_reached" | "inconclusive" | "new";

export type RetestItem = {
  finding_index?: number;
  title: string;
  kind?: string;
  severity?: string;
  original_step?: number | null;
  original_url?: string | null;
  label: RetestLabel;
  // Which pass produced the label: the independent visit, or the guided follow-up along the original route.
  pass?: "independent" | "guided" | null;
  // A step of this (the retest's) report.
  evidence_step: number | null;
  reason?: string;
  basis?: "observed";
};

export type RetestVerdictSide = {
  kind: VerdictKind;
  headline: string;
  where_step: number | null;
  where_url: string | null;
} | null;

export type RetestResult = {
  original_run_id?: string;
  labels: RetestItem[];
  new: RetestItem[];
  counts?: Record<string, number>;
  verdict?: { before: RetestVerdictSide; after: RetestVerdictSide; change: string; summary: string };
  fixed_means?: string;
  guided?: { attempted: number; followed: number };
  error?: string;
};

export type Run = {
  id: string;
  url: string;
  start_url: string | null;
  has_test_login: boolean;
  access_mode: AccessMode | null;
  first_impression: FirstImpression | null;
  entry: Entry | null;
  findings: Finding[] | null;
  verdict: Verdict | null;
  run_facts: RunFacts | null;
  success_condition: string | null;
  retest_of: string | null;
  retest: RetestResult | null;
  goal: string;
  status: RunStatus;
  outcome: Outcome | null;
  reason: string | null;
  cost_usd: number | string | null;
  brain_model: string | null;
  created_at: string;
  started_at: string | null;
  finished_at: string | null;
};

export type Step = {
  idx: number;
  tool: string;
  thought: string | null;
  input: Record<string, unknown> | null;
  result: Record<string, unknown> | null;
  url: string | null;
  screenshot_path: string | null;
  created_at: string;
};

export type Friction = {
  id: number;
  step_idx: number | null;
  kind: "site" | "agent_issue";
  severity: "low" | "medium" | "high" | null;
  expected: string | null;
  happened: string | null;
};

// The original of a retest, and the latest check of a run (either may be absent).
export type RunLink = { id: string; status?: string; verdict?: Verdict | null; outcome?: Outcome | null };

export type RunDetails = {
  run: Run;
  steps: Step[];
  frictions: Friction[];
  original?: RunLink | null;
  latest_retest?: RunLink | null;
};

export type ApiError = { error: string; message: string };

// Never includes the test login: it lives in run_secrets, which the web app never reads.
// One string literal, so supabase-js can infer the row type from it.
