332	  suggestions: string[];
333	};
334	
335	// What happened after the visitor submitted a login or sign-up form (worker/login_diagnosis.py).
336	export type LoginDiagnosis = {
337	  stage: "sign_in" | "sign_up";
338	  result: "signed_in" | "rejected" | "needs_verification" | "no_effect";
339	  challenge: "email_verification" | "captcha" | "two_factor" | null;
340	  page_message: string | null;
341	  http_statuses: string[];
342	  step: number | null;
343	  url: string | null;
344	  detail?: string;
345	};
346	
347	// Which way in the visit used. Never holds a credential: the test login's values are not stored here.
348	export type Entry = {
349	  start_link: string | null;
350	  access_mode?: AccessMode;
351	  // A login written on the page itself (a demo login for visitors), typed with the page's own values.
352	  page_login?: "not_used" | "shown_on_page" | "typed";
353	  // That login was accepted: the password field went away and the visit moved on. Absent on older runs.
354	  page_login_worked?: boolean;
355	  diagnosis?: LoginDiagnosis | null;
356	  // The site showed a bot check ("Verify you are human"); the visit did not try to get past it.
357	  bot_check?: { phrase: string; url: string; title: string; step: number } | null;
358	  test_login: "not_provided" | "provided_not_used" | "used" | "failed";
359	  self_signup: "not_used" | "used" | "blocked_verification" | "blocked_third_party" | "failed";
360	  third_party_options: string[];
361	  created_account_email: string | null;
362	  blocked_at_login: boolean;
363	};
364	
365	// One ranked problem from the report writer (worker/report_writer.py). Every one points at a real step.
366	export type Finding = {
367	  title: string;
368	  severity: "high" | "medium" | "low";
369	  kind: "site_problem" | "unclear_wording" | "hidden_error";
370	  expected: string;
371	  happened: string;
372	  evidence: {
373	    step: number;
374	    url: string | null;
375	    screenshot_url: string | null;
376	    page_errors: string[];
377	    quote: string | null;
378	  };
379	  reproduce: string[];
380	  fix_prompt: string;
381	  // Steps of the problems the visitor noted that this finding covers, so they are not listed twice.
382	  covers_steps?: number[];
383	  // The problem is observed in the run; the fix is our recommendation. Absent on older findings.
384	  basis?: "observed";
385	  fix_basis?: "recommendation";
386	  // Three to five checks a person can make by looking at the page after the change.
387	  acceptance_criteria?: string[];
388	  // The same symptom seen again, merged into this finding: the earliest step is `evidence`, these are the rest.
389	  also_seen_at?: { step: number; url: string | null; screenshot_url: string | null; page_errors: string[] }[];
390	};
391	
392	// What a statement in the report rests on: the run record, the independent check, or our suggestion.
393	export type Basis = "observed" | "verified" | "recommendation";
394	
395	export type VerdictKind = "got_through" | "unconfirmed" | "stuck" | "login_wall" | "bot_check" | "our_failure";
396	
397	// One verdict per run (worker/verdict.py).
398	export type Verdict = {
399	  kind: VerdictKind;
400	  headline: string;
401	  where_step: number | null;
402	  where_url: string | null;
403	  evidence_quote: string;
404	  basis: "observed" | "verified";
405	  detail?: string;
406	  ways_in?: string[];
407	};
408	
409	// How the report was made (worker/run_facts.py): counted from the run, not written by a model.
410	export type RunFacts = {
411	  steps_taken: number;
412	  recoveries: { step: number; rung: string; how: string; instruction: string }[];
413	  own_issues: { step: number | null; instruction: string; reason: string | null }[];
414	  page_reloads: number;
415	  page_errors: string[];
416	  page_error_count: number;
417	  verifier: { verdict: string | null; quote: string } | null;
418	  success_condition: string | null;
419	  checked_without_success_condition: boolean;
420	  cost_usd: number;
421	  duration_seconds: number;
422	  agent_version?: string;
423	  worker_id?: string;
424	  trace_id?: string | null;
425	};
426	
427	// Check again (worker/retest.py): what happened to each finding of the original run.
428	export type RetestLabel = "fixed" | "still_present" | "not_reached" | "inconclusive" | "new";
429	
430	export type RetestItem = {
431	  finding_index?: number;
432	  title: string;
433	  kind?: string;
434	  severity?: string;
435	  original_step?: number | null;
436	  original_url?: string | null;
437	  label: RetestLabel;
438	  // Which pass produced the label: the independent visit, or the guided follow-up along the original route.
439	  pass?: "independent" | "guided" | null;
440	  // A step of this (the retest's) report.
441	  evidence_step: number | null;
442	  reason?: string;
443	  basis?: "observed";
444	};
445	
446	export type RetestVerdictSide = {
447	  kind: VerdictKind;
448	  headline: string;
449	  where_step: number | null;
450	  where_url: string | null;
451	} | null;
452	
453	export type RetestResult = {
454	  original_run_id?: string;
455	  labels: RetestItem[];
456	  new: RetestItem[];
457	  counts?: Record<string, number>;
458	  verdict?: { before: RetestVerdictSide; after: RetestVerdictSide; change: string; summary: string };
459	  fixed_means?: string;
460	  guided?: { attempted: number; followed: number };
461	  error?: string;
462	};
463	
464	export type Run = {
465	  id: string;
466	  url: string;
467	  start_url: string | null;
468	  has_test_login: boolean;
469	  access_mode: AccessMode | null;
470	  first_impression: FirstImpression | null;
471	  entry: Entry | null;
472	  findings: Finding[] | null;
473	  verdict: Verdict | null;
474	  run_facts: RunFacts | null;
475	  success_condition: string | null;
476	  retest_of: string | null;
477	  retest: RetestResult | null;
478	  goal: string;
479	  status: RunStatus;
480	  outcome: Outcome | null;
481	  reason: string | null;
482	  cost_usd: number | string | null;
483	  brain_model: string | null;
484	  created_at: string;
485	  started_at: string | null;
486	  finished_at: string | null;
487	};
488	
489	export type Step = {
490	  idx: number;
491	  tool: string;
492	  thought: string | null;
493	  input: Record<string, unknown> | null;
494	  result: Record<string, unknown> | null;
495	  url: string | null;
496	  screenshot_path: string | null;
497	  created_at: string;
498	};
499	
500	export type Friction = {
501	  id: number;
502	  step_idx: number | null;
503	  kind: "site" | "agent_issue";
504	  severity: "low" | "medium" | "high" | null;
505	  expected: string | null;
506	  happened: string | null;
507	};
508	
509	// The original of a retest, and the latest check of a run (either may be absent).
510	export type RunLink = { id: string; status?: string; verdict?: Verdict | null; outcome?: Outcome | null };
511	
512	export type RunDetails = {
513	  run: Run;
514	  steps: Step[];
515	  frictions: Friction[];
516	  original?: RunLink | null;
517	  latest_retest?: RunLink | null;
518	};
519	
520	export type ApiError = { error: string; message: string };
521	
522	// Never includes the test login: it lives in run_secrets, which the web app never reads.
523	// One string literal, so supabase-js can infer the row type from it.
524	export const RUN_COLUMNS =
525	  "id, url, start_url, has_test_login, access_mode, first_impression, entry, findings, verdict, run_facts, success_condition, retest_of, retest, goal, status, outcome, reason, cost_usd, brain_model, created_at, started_at, finished_at";
526	// The same without the columns added on 2026-10-11 (access_mode, findings), for a database whose schema
527	// has not been updated yet: the run page still loads, without them.
528	export const RUN_COLUMNS_BEFORE_FINDINGS = RUN_COLUMNS.replace(" access_mode,", "")
529	  .replace(" findings,", "")
530	  .replace(" verdict,", "")
531	  .replace(" run_facts,", "")
532	  .replace(" success_condition,", "")
533	  .replace(" retest_of,", "")
534	  .replace(" retest,", "");
535	export const STEP_COLUMNS = "idx, tool, thought, input, result, url, screenshot_path, created_at";
536	export const FRICTION_COLUMNS = "id, step_idx, kind, severity, expected, happened";
537	// Small rules of the brief page and of starting a test from it, kept apart from the components so they
538	// can be tested with Node alone (npm test). Types only are imported: no runtime dependencies.
539	
540	import type { Brief, BriefClaim, BriefFailure, ClaimStatus } from "./brief-types.ts";
541	
542	export const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
543	export const MAX_GOAL_LENGTH = 500;
544	export const MAX_SUCCESS_LENGTH = 300;
545	
546	export function isBrief(value: unknown): value is Brief {
547	  const brief = value as Brief | null;
548	  return !!brief && typeof brief === "object" && typeof brief.one_liner === "string" && Array.isArray(brief.claims);
549	}
550	
551	export function isFailure(value: unknown): value is BriefFailure {
552	  const failure = value as BriefFailure | null;
553	  return !!failure && typeof failure === "object" && failure.status === "could_not_read";
554	}
555	
556	// Only http(s) addresses become links: a page's own text never gets to write a javascript: link.
557	export function safeHref(url: string | null | undefined): string | null {
558	  if (!url) return null;
559	  try {
560	    const parsed = new URL(url);
561	    return parsed.protocol === "https:" || parsed.protocol === "http:" ? parsed.href : null;
562	  } catch {
563	    return null;
564	  }
565	}
566	
567	const STATUS_ORDER: ClaimStatus[] = ["confirmed", "inferred", "unknown"];
568	
569	// Stated on the site first, then inferred, then unknown. Stable inside each group.
570	export function sortClaims(claims: BriefClaim[]): BriefClaim[] {
571	  return claims
572	    .map((claim, index) => ({ claim, index }))
573	    .sort((a, b) => STATUS_ORDER.indexOf(a.claim.status) - STATUS_ORDER.indexOf(b.claim.status) || a.index - b.index)
574	    .map(({ claim }) => claim);
575	}
576	
577	// The address the test form opens at for one journey, with the goal and success as the visitor edited them.
578	export function testJourneyHref(briefId: string, siteUrl: string, goal: string, success: string): string {
579	  const params = new URLSearchParams();
580	  params.set("mode", "test");
581	  params.set("url", siteUrl);
582	  params.set("goal", goal.trim().slice(0, MAX_GOAL_LENGTH));
583	  if (success.trim()) params.set("success", success.trim().slice(0, MAX_SUCCESS_LENGTH));
584	  params.set("brief", briefId);
585	  return `/?${params.toString()}`;
586	}
587	
588	export type HomeParams = { mode: "test" | "understand"; url: string; goal: string; success: string; brief: string };
589	
590	// What the home page takes from its address, with anything odd dropped.
591	export function parseHomeParams(raw: Record<string, string | string[] | undefined>): HomeParams {
592	  const one = (key: string) => {
593	    const value = raw[key];
594	    return typeof value === "string" ? value : Array.isArray(value) ? (value[0] ?? "") : "";
595	  };
596	  const brief = one("brief");
597	  return {
598	    mode: one("mode") === "understand" ? "understand" : "test",
599	    url: one("url").slice(0, 2048),
600	    goal: one("goal").slice(0, MAX_GOAL_LENGTH),
601	    success: one("success").slice(0, MAX_SUCCESS_LENGTH),
602	    brief: UUID.test(brief) ? brief : "",
603	  };
604	}
605	import "server-only";
606	
607	import { createHmac } from "node:crypto";
608	
609	// The first address in X-Forwarded-For is the client when a trusted proxy
610	// (such as Vercel) sets the header. Without such a proxy it can be forged, so
611	// the rate limit is a speed bump, not a guarantee.
612	export function clientIp(headers: Headers): string {
613	  const forwarded = headers.get("x-forwarded-for")?.split(",")[0]?.trim();
614	  return forwarded || headers.get("x-real-ip")?.trim() || "unknown";
615	}
616	
617	// A keyed hash, so the stored value cannot be reversed by hashing every IPv4
618	// address. IP_HASH_SECRET is optional; the service role key is already a
619	// server-only secret, so it is the fallback key.
620	export function hashIp(ip: string): string {
621	  const secret = process.env.IP_HASH_SECRET || process.env.SUPABASE_SERVICE_ROLE_KEY;
622	  if (!secret) throw new Error("No secret available to hash visitor IPs");
623	  return createHmac("sha256", secret).update(ip).digest("hex");
624	}
625	import "server-only";
626	
627	import { lookup } from "node:dns/promises";
628	import { isIP } from "node:net";
629	
630	export type UrlCheck = { ok: true; url: string } | { ok: false; message: string };
631	
632	const MAX_URL_LENGTH = 2048;
633	const BLOCKED_SUFFIXES = [".localhost", ".local", ".internal", ".intranet", ".lan", ".home.arpa", ".corp"];
634	const DNS_TIMEOUT_MS = 3000;
635	
636	const PRIVATE_MESSAGE =
637	  "That address points to a private or local network. Use your app's public address, the one a visitor would type.";
638	
639	/**
640	 * Accept only a public http(s) address on the default port. The worker's
641	 * browser resolves the name again later and the site can redirect, so this
642	 * stops honest mistakes and casual abuse, not a determined DNS-rebinding attack.
643	 */
644	export async function checkTargetUrl(input: string): Promise<UrlCheck> {
645	  const text = input.trim();
646	  if (!text) return { ok: false, message: "Enter your app's address." };
647	  if (text.length > MAX_URL_LENGTH) return { ok: false, message: "That address is too long." };
648	
649	  let url: URL;
650	  try {
651	    url = new URL(/^[a-z][a-z0-9+.-]*:/i.test(text) ? text : `https://${text}`);
652	  } catch {
653	    return { ok: false, message: "That doesn't look like a web address. Try something like https://example.com." };
654	  }
655	
656	  if (url.protocol !== "http:" && url.protocol !== "https:") {
657	    return { ok: false, message: "Only http:// and https:// addresses can be tested." };
658	  }
659	  if (url.username || url.password) {
660	    return { ok: false, message: "Remove the username and password from the address." };
661	  }
662	  // The URL parser drops default ports (80 for http, 443 for https), so any port left is unusual.
663	  if (url.port) {
664	    return { ok: false, message: "Use your app's public address without a port number (like :3000)." };
665	  }
666	
667	  const host = url.hostname.toLowerCase().replace(/^\[|\]$/g, "").replace(/\.$/, "");
668	  if (isIP(host)) {
669	    if (isPrivateAddress(host)) return { ok: false, message: PRIVATE_MESSAGE };
670	  } else {
671	    if (host === "localhost" || BLOCKED_SUFFIXES.some((suffix) => host.endsWith(suffix))) {
672	      return { ok: false, message: PRIVATE_MESSAGE };
673	    }
674	    if (!host.includes(".")) {
675	      return { ok: false, message: "Use the full public address of your app, like https://example.com." };
676	    }
677	    let addresses: { address: string }[];
678	    try {
679	      addresses = await withTimeout(lookup(host, { all: true, verbatim: true }), DNS_TIMEOUT_MS);
680	    } catch {
681	      return { ok: false, message: `We couldn't find a site at ${host}. Check the address and try again.` };
682	    }
683	    if (addresses.length === 0 || addresses.some(({ address }) => isPrivateAddress(address))) {
684	      return { ok: false, message: PRIVATE_MESSAGE };
685	    }
686	  }
687	
688	  url.hash = "";
689	  return { ok: true, url: url.href };
690	}
691	
692	function withTimeout<T>(promise: Promise<T>, ms: number): Promise<T> {
693	  return new Promise((resolve, reject) => {
694	    const timer = setTimeout(() => reject(new Error("timeout")), ms);
695	    promise.then(
696	      (value) => {
697	        clearTimeout(timer);
698	        resolve(value);
699	      },
700	      (error) => {
701	        clearTimeout(timer);
702	        reject(error);
703	      },
704	    );
705	  });
706	}
707	
708	export function isPrivateAddress(address: string): boolean {
709	  const version = isIP(address);
710	  if (version === 4) return isPrivateIPv4(address);
711	  if (version === 6) return isPrivateIPv6(address);
712	  return true;
713	}
714	
715	function isPrivateIPv4(address: string): boolean {
716	  const [a, b, c] = address.split(".").map(Number);
717	  return (
718	    a === 0 || // "this" network
719	    a === 10 || // private
720	    a === 127 || // loopback
721	    (a === 100 && b >= 64 && b <= 127) || // carrier-grade NAT
722	    (a === 169 && b === 254) || // link-local, including cloud metadata
723	    (a === 172 && b >= 16 && b <= 31) || // private
724	    (a === 192 && b === 0 && (c === 0 || c === 2)) || // protocol assignments, documentation
725	    (a === 192 && b === 168) || // private
726	    (a === 198 && (b === 18 || b === 19)) || // benchmarking
727	    (a === 198 && b === 51 && c === 100) || // documentation
728	    (a === 203 && b === 0 && c === 113) || // documentation
729	    a >= 224 // multicast, reserved, broadcast
730	  );
731	}
732	
733	function isPrivateIPv6(address: string): boolean {
734	  const groups = expandIPv6(address);
735	  if (!groups) return true;
736	  const zeros = (from: number, to: number) => groups.slice(from, to).every((g) => g === 0);
737	
738	  if (zeros(0, 8)) return true; // ::
739	  if (zeros(0, 7) && groups[7] === 1) return true; // ::1
740	  if (zeros(0, 5) && groups[5] === 0xffff) return isPrivateIPv4(embeddedIPv4(groups)); // ::ffff:a.b.c.d
741	  if (zeros(0, 6)) return isPrivateIPv4(embeddedIPv4(groups)); // deprecated ::a.b.c.d
742	  if (groups[0] === 0x64 && groups[1] === 0xff9b && zeros(2, 6)) return isPrivateIPv4(embeddedIPv4(groups)); // NAT64
743	
744	  const first = groups[0];
745	  return (
746	    (first & 0xfe00) === 0xfc00 || // unique local fc00::/7
747	    (first & 0xffc0) === 0xfe80 || // link-local fe80::/10
748	    (first & 0xff00) === 0xff00 || // multicast
749	    (first === 0x2001 && groups[1] === 0x0db8) // documentation
750	  );
751	}
752	
753	function embeddedIPv4(groups: number[]): string {
754	  return [groups[6] >> 8, groups[6] & 0xff, groups[7] >> 8, groups[7] & 0xff].join(".");
755	}
756	
757	function expandIPv6(address: string): number[] | null {
758	  let text = address.split("%")[0];
759	  const dotted = text.match(/(\d+)\.(\d+)\.(\d+)\.(\d+)$/);
760	  if (dotted) {
761	    const [a, b, c, d] = dotted.slice(1).map(Number);
762	    text = text.slice(0, -dotted[0].length) + `${((a << 8) | b).toString(16)}:${((c << 8) | d).toString(16)}`;
763	  }
764	  const halves = text.split("::");
765	  if (halves.length > 2) return null;
766	  const parse = (part: string) => (part ? part.split(":").map((g) => parseInt(g, 16)) : []);
767	  const head = parse(halves[0]);
768	  const tail = halves.length === 2 ? parse(halves[1]) : [];
769	  const missing = 8 - head.length - tail.length;
770	  if (missing < 0 || (halves.length === 1 && missing !== 0)) return null;
771	  const groups = [...head, ...Array<number>(missing).fill(0), ...tail];
772	  return groups.some((g) => Number.isNaN(g) || g < 0 || g > 0xffff) ? null : groups;
773	}
