491	            {inFindings > 0
492	              ? "Everything the visitor noted is in the findings above."
493	              : "The visitor didn\u2019t note any problems."}
494	          </p>
495	        ) : (
496	          <ul className="space-y-3">
497	            {site.map((friction) => (
498	              <FrictionItem key={friction.id} friction={friction} />
499	            ))}
500	          </ul>
501	        )}
502	      </div>
503	      <div className="space-y-3">
504	        <h2 className="text-xl font-semibold tracking-tight">Our agent&apos;s own issues</h2>
505	        <p className="text-sm text-muted">
506	          Times our browser tool couldn&apos;t operate something. These are likely our fault, not your site&apos;s.
507	        </p>
508	        {ours.length === 0 ? (
509	          <p className="text-muted">None.</p>
510	        ) : (
511	          <ul className="space-y-3">
512	            {ours.map((friction) => (
513	              <FrictionItem key={friction.id} friction={friction} />
514	            ))}
515	          </ul>
516	        )}
517	      </div>
518	    </section>
519	  );
520	}
521	
522	const FINDING_KIND: Record<Finding["kind"], string> = {
523	  site_problem: "Site problem",
524	  unclear_wording: "Unclear wording",
525	  hidden_error: "Hidden error",
526	};
527	
528	// The report's ranked problems, most likely to stop a new user first, each with a prompt to paste
529	// into a coding agent. Every one points at a step of the visit.
530	function Findings({ run, flags }: { run: Run; flags: ReportFlags }) {
531	  const findings = run.findings;
532	  if (findings === null) return null; // from before the report writer, or it could not be written
533	  // The same ids the feedback route uses, so a vote lands on the right finding.
534	  const ids = findingIds(findings);
535	  const showFeedback = flags.feedback && feedbackShown(run);
536	  return (
537	    <section className="space-y-4" aria-labelledby="findings">
538	      <div>
539	        <h2 id="findings" className="text-xl font-semibold tracking-tight">
540	          What to fix first
541	        </h2>
542	        <p className="mt-1 text-sm text-muted">
543	          Ranked by how likely each is to stop a new user. Each one points at a step below.
544	        </p>
545	      </div>
546	      {findings.length === 0 ? (
547	        <p className="rounded-xl border border-line bg-surface p-4 text-muted">
548	          Nothing in this visit stood out as a problem with your site.
549	        </p>
550	      ) : (
551	        <ol className="space-y-4">
552	          {findings.map((finding, index) => (
553	            <FindingCard
554	              key={index}
555	              finding={finding}
556	              rank={index + 1}
557	              flags={flags}
558	              feedback={
559	                showFeedback && (
560	                  <FindingFeedback runId={run.id} findingId={ids[index]} checkAgain={flags.checkAgain} />
561	                )
562	              }
563	            />
564	          ))}
565	        </ol>
566	      )}
567	    </section>
568	  );
569	}
570	
571	function FindingCard({ finding, rank, flags, feedback }: {
572	  finding: Finding;
573	  rank: number;
574	  flags: ReportFlags;
575	  feedback?: ReactNode;
576	}) {
577	  const evidence = finding.evidence;
578	  return (
579	    <li className="space-y-4 rounded-xl border border-line bg-surface p-4 sm:p-5">
580	      <div className="space-y-2">
581	        <div className="flex flex-wrap items-center gap-2 text-sm">
582	          <span className="text-subtle tabular-nums">{rank}.</span>
583	          <span className={`rounded-full px-2.5 py-0.5 font-medium ${SEVERITY_TONE[finding.severity]}`}>
584	            {finding.severity}
585	          </span>
586	          <span className="rounded-full border border-line px-2.5 py-0.5 text-muted">{FINDING_KIND[finding.kind]}</span>
587	          <BasisBadge basis="observed" show={flags.labels && finding.basis !== undefined} />
588	        </div>
589	        <h3 className="text-lg font-semibold leading-snug">{finding.title}</h3>
590	      </div>
591	      <dl className="space-y-2">
592	        <div>
593	          <dt className="text-sm text-subtle">What the visitor expected</dt>
594	          <dd>{finding.expected}</dd>
595	        </div>
596	        <div>
597	          <dt className="text-sm text-subtle">What happened</dt>
598	          <dd>{finding.happened}</dd>
599	        </div>
600	      </dl>
601	      <div className="space-y-2 text-sm">
602	        <p className="font-medium">Evidence</p>
603	        <ul className="list-disc space-y-1 pl-5 text-muted">
604	          <li>
605	            <a href={`#step-${evidence.step}`} className="text-accent hover:underline">
