607	            </a>
608	            {evidence.url && <span> on {displayUrl(evidence.url)}</span>}
609	          </li>
610	          {(finding.also_seen_at?.length ?? 0) > 0 && (
611	            <li>
612	              Seen again at{" "}
613	              {finding.also_seen_at!.map((seen, index) => (
614	                <span key={seen.step}>
