617	                    step {seen.step}
618	                  </a>
619	                </span>
620	              ))}
621	            </li>
622	          )}
623	          {evidence.quote && <li>The page said: &ldquo;{evidence.quote}&rdquo;</li>}
624	          {evidence.page_errors.map((error, index) => (
625	            <li key={index}>
