657	              <li key={index}>{line}</li>
658	            ))}
659	          </ol>
660	        </div>
661	      )}
662	      <div className="flex flex-wrap items-center gap-2 text-sm">
663	        <span className="text-subtle">The fix prompt below is</span>
664	        <BasisBadge basis="recommendation" show={flags.labels} />
665	      </div>
666	      <FixPrompt prompt={finding.fix_prompt} />
667	      {feedback}
668	    </li>
669	  );
670	}
671	
672	// The clipboard API needs a secure, focused page; a hidden textarea and execCommand cover the rest.
673	async function copyText(value: string): Promise<boolean> {
674	  try {
675	    await navigator.clipboard.writeText(value);
676	    return true;
677	  } catch {
678	    try {
679	      const box = document.createElement("textarea");
680	      box.value = value;
681	      box.setAttribute("readonly", "");
682	      box.style.position = "fixed";
683	      box.style.opacity = "0";
684	      document.body.appendChild(box);
685	      box.select();
686	      const ok = document.execCommand("copy");
687	      document.body.removeChild(box);
688	      return ok;
689	    } catch {
690	      return false;
691	    }
692	  }
693	}
694	
695	function FixPrompt({ prompt }: { prompt: string }) {
696	  const [copied, setCopied] = useState<"idle" | "copied" | "failed">("idle");
697	  async function copy() {
698	    setCopied((await copyText(prompt)) ? "copied" : "failed");
699	  }
700	  return (
701	    <div className="space-y-2">
702	      <div className="flex flex-wrap items-center gap-3">
703	        <button
704	          type="button"
705	          onClick={copy}
706	          className="rounded-lg bg-accent px-4 py-2 text-sm font-medium text-white hover:bg-accent-strong focus:outline-none focus-visible:ring-2 focus-visible:ring-accent/40 dark:text-background"
707	        >
708	          Copy fix prompt
709	        </button>
710	        <span aria-live="polite" className="text-sm text-muted">
711	          {copied === "copied" && "Copied. Paste it into your coding agent."}
712	          {copied === "failed" && "Couldn't copy. Select the prompt below and copy it."}
713	        </span>
714	      </div>
715	      <details className="text-sm">
716	        <summary className="cursor-pointer text-muted">Show the prompt</summary>
717	        <pre className="mt-2 whitespace-pre-wrap break-words rounded-lg border border-line bg-background p-3 font-mono text-[13px] leading-relaxed">
718	          {prompt}
719	        </pre>
720	      </details>
721	    </div>
722	  );
723	}
724	
725	const SEVERITY_TONE = {
726	  high: "bg-danger-soft text-danger",
727	  medium: "bg-warning-soft text-warning",
728	  low: "bg-background text-muted border border-line",
729	};
730	
731	function FrictionItem({ friction }: { friction: Friction }) {
732	  if (friction.kind === "agent_issue") {
733	    // The worker writes expected as "'<instruction>' changes the page"; show the instruction alone.
734	    const instruction = friction.expected?.match(/^'(.*)' changes the page$/)?.[1] ?? friction.expected;
735	    return (
736	      <li className="space-y-2 rounded-xl border border-line bg-surface p-4">
737	        {friction.step_idx !== null && (
738	          <a href={`#step-${friction.step_idx}`} className="text-sm text-accent hover:underline">
739	            Step {friction.step_idx}
740	          </a>
741	        )}
742	        {instruction && (
743	          <p>
744	            <span className="text-subtle">Tried to: </span>
745	            {instruction}
746	          </p>
747	        )}
748	        <p className="text-muted">Nothing on the page changed after three different attempts.</p>
749	      </li>
750	    );
751	  }
752	  return (
753	    <li className="space-y-2 rounded-xl border border-line bg-surface p-4">
754	      <div className="flex flex-wrap items-center gap-2 text-sm">
755	        {friction.severity && (
756	          <span className={`rounded-full px-2.5 py-0.5 font-medium ${SEVERITY_TONE[friction.severity]}`}>
757	            {friction.severity}
758	          </span>
759	        )}
760	        {friction.step_idx !== null && (
761	          <a href={`#step-${friction.step_idx}`} className="text-accent hover:underline">
762	            Step {friction.step_idx}
763	          </a>
764	        )}
765	      </div>
766	      {friction.expected && (
767	        <p>
768	          <span className="text-subtle">Expected: </span>
769	          {friction.expected}
770	        </p>
771	      )}
772	      {friction.happened && (
773	        <p>
774	          <span className="text-subtle">What happened: </span>
775	          {friction.happened}
776	        </p>
777	      )}
778	    </li>
779	  );
780	}
781	
782	function Timeline({ steps }: { steps: Step[] }) {
783	  return (
784	    <section className="space-y-4">
785	      <h2 className="text-xl font-semibold tracking-tight">Step by step</h2>
786	      <ol className="space-y-4">
787	        {steps.map((step) => (
788	          <StepItem key={step.idx} step={step} />
789	        ))}
790	      </ol>
791	    </section>
792	  );
793	}
794	
795	function StepItem({ step }: { step: Step }) {
796	  const result = describeResult(step);
797	  return (
798	    <li id={`step-${step.idx}`} className="scroll-mt-6 space-y-3 rounded-xl border border-line bg-surface p-4 sm:p-5">
799	      <div className="flex flex-wrap items-baseline justify-between gap-x-4 gap-y-1">
800	        <p className="font-medium">
801	          <span className="mr-2 text-subtle tabular-nums">{step.idx}.</span>
802	          {describeAction(step)}
803	        </p>
804	        {step.url && <p className="min-w-0 truncate text-sm text-subtle">{displayUrl(step.url)}</p>}
805	      </div>
806	      {step.thought && <p className="border-l-2 border-line pl-3 italic text-muted">{step.thought}</p>}
807	      {result && <p className={result.tone === "warn" ? "text-warning" : ""}>{result.text}</p>}
808	      {isHttpUrl(step.screenshot_path) && (
809	        <a href={step.screenshot_path} target="_blank" rel="noopener noreferrer" className="block">
810	          {/* Screenshots are stored in Supabase Storage; a plain img avoids configuring remote image hosts. */}
811	          {/* eslint-disable-next-line @next/next/no-img-element */}
812	          <img
813	            src={step.screenshot_path}
814	            alt={`The page after step ${step.idx}`}
815	            loading="lazy"
816	            className="w-full rounded-lg border border-line"
817	          />
818	        </a>
819	      )}
820	    </li>
821	  );
822	}
823	
824	function describeAction(step: Step): string {
825	  const input = step.input ?? {};
826	  switch (step.tool) {
827	    case "look":
828	      return "Looked at the page";
829	    case "do":
830	      return `Tried to ${text(input.instruction) || "act on the page"}`;
831	    case "scroll":
832	      return `Scrolled ${text(input.direction) || "the page"}`;
833	    case "go_back":
834	      return "Went back";
835	    case "note_friction":
836	      return "Noted a problem";
837	    case "finish":
838	      return "Ended the visit";
839	    default:
840	      return step.tool;
841	  }
842	}
843	
844	function describeResult(step: Step): { text: string; tone?: "warn" } | null {
845	  const result = step.result ?? {};
846	  const input = step.input ?? {};
847	  if (result.error) return { text: "The browser tool hit an error on this step.", tone: "warn" };
848	  switch (step.tool) {
849	    case "look":
850	      return result.unchanged
851	        ? { text: "Nothing had changed since the last look." }
852	        : { text: tidySummary(text(result.summary)) };
853	    case "do":
854	      if (result.success) return { text: RETRY_WORDING[text(result.rung)] ?? "It worked." };
855	      return {
856	        text: "Nothing happened. Our browser tool may have failed here, so this is logged as our issue.",
857	        tone: "warn",
858	      };
859	    case "note_friction":
860	      return { text: `Expected: ${text(input.expected)} What happened: ${text(input.happened)}` };
861	    case "finish":
862	      return { text: text(input.reason) };
863	    default:
864	      return null;
865	  }
866	}
867	
868	// Which try of the worker's recovery ladder changed the page (see worker/tools.py do()).
869	const RETRY_WORDING: Record<string, string> = {
870	  b: "The first try had no effect. It worked on the second try, after our browser tool looked for the element again.",
871	  c: "The first two tries had no effect. It worked on the third try, with a direct click on the element.",
872	};
873	
874	// The worker caps summaries at this length; older runs cut them mid-word.
875	const SUMMARY_LIMIT = 400;
876	
877	function tidySummary(summary: string): string {
878	  const trimmed = summary.trim();
879	  if (summary.length < SUMMARY_LIMIT || /[.!?…)"']$/.test(trimmed)) return trimmed;
880	  const lastSpace = trimmed.lastIndexOf(" ");
881	  const cut = lastSpace > SUMMARY_LIMIT / 2 ? trimmed.slice(0, lastSpace) : trimmed;
882	  return `${cut.replace(/[\s,;:-]+$/, "")}…`;
883	}
884	
885	function ConnectionNotice() {
886	  return (
887	    <p role="status" className="rounded-lg border border-warning/30 bg-warning-soft p-3 text-sm text-warning">
888	      Having trouble reaching the server. Still trying…
889	    </p>
890	  );
891	}
892	
893	function NotFound() {
894	  return (
895	    <section className="space-y-4">
896	      <h1 className="text-2xl font-semibold tracking-tight">We couldn&apos;t find that run</h1>
897	      <p className="text-muted">The link may be mistyped or incomplete. Check it, or start a new run.</p>
898	      <Link href="/" className="inline-block font-medium text-accent hover:underline">
899	        Start a new run
900	      </Link>
901	    </section>
902	  );
903	}
904	
905	function text(value: unknown): string {
906	  return typeof value === "string" ? value : "";
907	}
908	
909	function isHttpUrl(value: string | null): value is string {
910	  return !!value && /^https?:\/\//i.test(value);
911	}
912	
913	function displayUrl(url: string): string {
914	  try {
915	    const parsed = new URL(url);
916	    const path = parsed.pathname === "/" ? "" : parsed.pathname;
917	    return `${parsed.host}${path}${parsed.search}`;
918	  } catch {
919	    return url;
920	  }
921	}
922	
923	function duration(start: string | null, end: string | null): string {
924	  if (!start || !end) return "—";
925	  const seconds = Math.max(0, Math.round((Date.parse(end) - Date.parse(start)) / 1000));
926	  if (seconds < 60) return `${seconds} s`;
927	  return `${Math.floor(seconds / 60)} min ${seconds % 60} s`;
928	}
929	
930	function formatCost(cost: number | string | null): string {
931	  if (cost === null || cost === "") return "—";
932	  const value = Number(cost);
933	  return Number.isFinite(value) ? `$${value.toFixed(value < 0.1 ? 4 : 2)}` : "—";
934	}
