"use client";

// Report v2: the three answers, the verdict, the evidence labels and the run facts. Kept in its own file
// so the report page can show or hide each one by flag (lib/report-flags.ts).

import type { ReactNode } from "react";

import {
  BASIS_LABEL,
  BASIS_NOTE,
  fixFirst,
  shortUrl,
  understanding,
  withoutPromises,
} from "@/lib/report-logic";
import type { Basis, Run, RunFacts, Step, Verdict, VerdictKind } from "@/lib/types";

const BASIS_TONE: Record<Basis, string> = {
  observed: "border-line text-muted",
  verified: "border-success/30 bg-success-soft text-success",
  recommendation: "border-accent/40 text-accent",
};

// A small label saying what a statement rests on. Hidden with the labels flag.
export function BasisBadge({ basis, show = true }: { basis: Basis; show?: boolean }) {
  if (!show) return null;
  return (
    <span
      title={BASIS_NOTE[basis]}
      className={`inline-block whitespace-nowrap rounded-full border px-2 py-0.5 text-xs font-medium ${BASIS_TONE[basis]}`}
    >
      {BASIS_LABEL[basis]}
    </span>
  );
}

const VERDICT_TONE: Record<VerdictKind, string> = {
  got_through: "border-success/30 bg-success-soft",
  unconfirmed: "border-warning/30 bg-warning-soft",
  stuck: "border-danger/30 bg-danger-soft",
  login_wall: "border-warning/30 bg-warning-soft",
  bot_check: "border-warning/30 bg-warning-soft",
  our_failure: "border-line bg-surface",
};

const VERDICT_WORD: Record<VerdictKind, string> = {
  got_through: "Got through",
  unconfirmed: "Not confirmed",
  stuck: "Got stuck",
  login_wall: "Stopped at a login",
  bot_check: "Blocked by a bot check",
  our_failure: "Failed on our side",
};

const LEVEL_TONE = {
  clear: "bg-success-soft text-success",
  partly: "bg-warning-soft text-warning",
  unclear: "bg-danger-soft text-danger",
};

function Answer({ question, answer, tone, children, basis, showBasis }: {
  question: string;
  answer: string;
  tone: string;
  children?: ReactNode;
  basis: Basis;
  showBasis: boolean;
}) {
  return (
    <div className="space-y-2 rounded-xl border border-line bg-surface p-4">
      <h3 className="text-sm font-medium text-subtle">{question}</h3>
      <p>
        <span className={`rounded-full px-2.5 py-0.5 text-sm font-semibold ${tone}`}>{answer}</span>
      </p>
      <div className="space-y-1 text-sm text-muted">{children}</div>
      <BasisBadge basis={basis} show={showBasis} />
    </div>
  );
}

// Will they understand it? Can they get value? What to fix first? Answered from the first impression,
// the verdict and the top finding.
export function ThreeAnswers({ run, showBasis }: { run: Run; showBasis: boolean }) {
  const understood = understanding(run.first_impression);
  const verdict = run.verdict;
  const first = fixFirst(run.findings, verdict);
  return (
    <section aria-labelledby="three-answers" className="space-y-3">
      <h2 id="three-answers" className="text-xl font-semibold tracking-tight">
        The short answer
      </h2>
      <div className="grid gap-3 sm:grid-cols-3">
        <Answer
          question="Will a new user understand it?"
          answer={understood ? understood.label : "Not assessed"}
          tone={understood ? LEVEL_TONE[understood.level] : "bg-background text-muted"}
          basis="observed"
          showBasis={showBasis}
        >
          {understood ? (
            understood.reasons.length > 0 ? (
              <ul className="list-disc space-y-1 pl-4">
                {understood.reasons.slice(0, 3).map((reason, index) => (
                  <li key={index}>{reason}</li>
                ))}
              </ul>
            ) : (
              <p>What it does, who it is for and the main action were all clear on the landing page.</p>
            )
          ) : (
            <p>The landing page could not be reviewed.</p>
          )}
        </Answer>

        <Answer
          question="Can they get value from it?"
          answer={verdict ? VERDICT_WORD[verdict.kind] : "Not assessed"}
          tone={
            verdict
              ? verdict.kind === "got_through"
                ? LEVEL_TONE.clear
                : verdict.kind === "stuck"
                  ? LEVEL_TONE.unclear
                  : LEVEL_TONE.partly
              : "bg-background text-muted"
          }
          basis={verdict?.basis ?? "observed"}
          showBasis={showBasis}
        >
          <p>{verdict ? verdict.headline : "This run has no verdict."}</p>
        </Answer>

        <Answer
          question="What should you fix first?"
          answer={
            first.state === "finding"
              ? first.finding.title
              : first.state === "none"
                ? "Nothing stood out"
                : first.state === "not_about_site"
                  ? "Nothing, from this visit"
                  : "Not available"
          }
          tone="bg-background text-foreground"
          basis={first.state === "finding" ? "recommendation" : "observed"}
          showBasis={showBasis}
        >
          {first.state === "finding" && (
            <p>
              Ranked first of the findings below.{" "}
              <a href="#findings" className="text-accent hover:underline">
                See the finding
              </a>
              .
            </p>
          )}
          {first.state === "none" && <p>Nothing in this visit stood out as a problem with your site.</p>}
          {first.state === "not_about_site" && (
            <p>This visit says nothing about your site, so there is nothing to fix from it.</p>
          )}
        </Answer>
      </div>
      {showBasis && (
        <p className="text-xs text-subtle">
          Each answer is labelled by what it rests on. <strong>Observed</strong>: from the record of the visit.{" "}
          <strong>Verified</strong>: confirmed by an independent check. <strong>Recommendation</strong>: our
          suggestion, not a measured result.
        </p>
      )}
    </section>
  );
}

// The verdict: one headline, what it rests on, where it happened, and for a login wall the ways in.
export function VerdictCard({ verdict, run, showBasis, showSuccess }: {
  verdict: Verdict;
  run: Run;
  showBasis: boolean;
  showSuccess: boolean;
}) {
  return (
    <div className={`space-y-3 rounded-xl border p-5 ${VERDICT_TONE[verdict.kind]}`}>
      <div className="flex flex-wrap items-center gap-2">
        <p className="text-lg font-semibold">{verdict.headline}</p>
        <BasisBadge basis={verdict.basis} show={showBasis} />
      </div>
      {verdict.evidence_quote && (
        <p className="text-foreground">
          <span className="text-subtle">
            {verdict.kind === "got_through"
              ? "What confirmed it: "
              : verdict.kind === "unconfirmed"
                ? "What the check could not see: "
                : "Evidence: "}
          </span>
          {verdict.evidence_quote}
        </p>
      )}
      {verdict.detail && verdict.kind !== "unconfirmed" && <p className="text-sm text-muted">{verdict.detail}</p>}
      {(verdict.where_step !== null || verdict.where_url) && (
        <p className="text-sm text-muted">
          {verdict.where_step !== null && (
            <a href={`#step-${verdict.where_step}`} className="text-accent hover:underline">
              Step {verdict.where_step}
            </a>
          )}
          {verdict.where_step !== null && verdict.where_url ? " on " : ""}
          {verdict.where_url ? shortUrl(verdict.where_url) : ""}
        </p>
      )}
      {verdict.kind === "login_wall" && verdict.ways_in && (
        <div className="space-y-2 text-sm">
          <p className="font-medium">Three ways in</p>
          <ol className="list-decimal space-y-1 pl-5">
            {verdict.ways_in.map((way, index) => (
              <li key={index}>{way}</li>
            ))}
          </ol>
        </div>
      )}
      {showSuccess && (
        <p className="text-sm text-muted">
          {run.success_condition ? (
            <>
              <span className="text-subtle">Success condition you gave: </span>
              {run.success_condition}
            </>
          ) : (
            "The goal was checked without a stated success condition."
          )}
        </p>
      )}
      {run.reason && run.outcome !== "achieved" && (
        <p className="text-sm text-muted">
          <span className="text-subtle">The visitor&apos;s own report: </span>
          {run.reason}
        </p>
      )}
    </div>
  );
}

function fmtDuration(seconds: number): string {
  const total = Math.max(0, Math.round(seconds));
  return total < 60 ? `${total} s` : `${Math.floor(total / 60)} min ${total % 60} s`;
}

// "How this report was made", collapsed. Everything here is counted from the run, none of it is written
// by a model. The trace id is plain text.
export function RunFactsPanel({ run, steps }: { run: Run; steps: Step[] }) {
  const facts: RunFacts | null = run.run_facts;
  const cost = facts ? facts.cost_usd : Number(run.cost_usd ?? 0);
  const rows: [string, ReactNode][] = [];
  rows.push(["Steps taken", String(facts?.steps_taken ?? steps.length)]);
  if (facts) {
    rows.push([
      "Actions that needed recovery",
      facts.recoveries.length === 0
        ? "None"
        : facts.recoveries.map((r) => `step ${r.step}, rung ${r.rung} (${r.how})`).join("; "),
    ]);
    rows.push([
      "Our own issues",
      facts.own_issues.length === 0
        ? "None"
        : `${facts.own_issues.length}: ` +
          facts.own_issues.map((i) => (i.step !== null ? `step ${i.step}` : "a step")).join(", ") +
          " (our browser tool had no effect; not the site's fault)",
    ]);
    rows.push(["Page reloads", String(facts.page_reloads)]);
    rows.push([
      "Page errors recorded",
      facts.page_error_count === 0 ? "None" : (
        <ul className="list-disc space-y-1 pl-4">
          {facts.page_errors.map((error, index) => (
            <li key={index} className="break-all">
              {error}
            </li>
          ))}
          {facts.page_error_count > facts.page_errors.length && (
            <li>and {facts.page_error_count - facts.page_errors.length} more</li>
          )}
        </ul>
      ),
    ]);
    rows.push([
      "Independent check",
      facts.verifier ? `${facts.verifier.verdict}: ${facts.verifier.quote}` : "Not run (the visitor did not claim to reach the goal)",
    ]);
    rows.push([
      "Success condition",
      facts.success_condition ?? "None given: the goal was checked as worded",
    ]);
  }
  rows.push(["Cost", `$${cost.toFixed(cost < 0.1 ? 4 : 2)}`]);
  rows.push([
    "Duration",
    facts ? fmtDuration(facts.duration_seconds) : run.started_at && run.finished_at
      ? fmtDuration((Date.parse(run.finished_at) - Date.parse(run.started_at)) / 1000)
      : "—",
  ]);
  if (facts?.agent_version) rows.push(["Agent version", facts.agent_version]);
  if (facts?.worker_id) rows.push(["Worker", facts.worker_id]);
  if (facts?.trace_id) rows.push(["neatlogs trace ID", <code key="t" className="break-all">{facts.trace_id}</code>]);

  return (
    <details className="rounded-xl border border-line bg-surface p-4">
      <summary className="cursor-pointer font-medium">How this report was made</summary>
      <dl className="mt-4 space-y-3 text-sm">
        {rows.map(([label, value]) => (
          <div key={label} className="grid gap-1 sm:grid-cols-[14rem_1fr]">
            <dt className="text-subtle">{label}</dt>
            <dd className="break-words">{value}</dd>
          </div>
        ))}
      </dl>
      <p className="mt-4 text-xs text-subtle">
        The visit is a simulated user, so treat findings as leads to check. Recommendations are our suggestions and
        promise no outcome.
      </p>
    </details>
  );
}

// A recommendation as the page shows it: our wording, labelled, never promising a result.
export function Recommendation({ text, showBasis }: { text: string; showBasis: boolean }) {
  const safe = withoutPromises(text);
  if (!safe) return null;
  return (
    <span>
      {safe} <BasisBadge basis="recommendation" show={showBasis} />
    </span>
  );
}

"use client";

// Check again: the button that re-runs a finished report's journey, and the page of a re-check, which puts
// the old verdict and the new one side by side and labels each old finding. Kept in its own file so the
// report page changes little and the feature can be hidden by flag (lib/report-flags.ts).

import Link from "next/link";
import { useRouter } from "next/navigation";
import { useState, type FormEvent } from "react";

import { shortUrl } from "@/lib/report-logic";
import type { RetestItem, RetestLabel, RetestResult, RetestVerdictSide, Run, RunLink } from "@/lib/types";

const LABEL_TEXT: Record<RetestLabel, string> = {
  fixed: "Fixed",
  still_present: "Still present",
  not_reached: "Not reached",
  inconclusive: "Inconclusive",
  new: "New",
};

const LABEL_TONE: Record<RetestLabel, string> = {
  fixed: "bg-success-soft text-success",
  still_present: "bg-danger-soft text-danger",
  not_reached: "bg-warning-soft text-warning",
  inconclusive: "bg-background text-muted border border-line",
  new: "bg-danger-soft text-danger",
};

const LABEL_MEANING: Record<RetestLabel, string> = {
  fixed: "The step was reached and the original failure was not reproduced under the tested conditions.",
  still_present: "The step was reached and the failure happened again.",
  not_reached: "The state was never reached, so this is unverified. It is not reported as fixed.",
  inconclusive: "The state was reached, but the evidence does not decide it.",
  new: "A problem this check found that was not in the original report.",
};

const PASS_TEXT = { independent: "Independent visit", guided: "Guided follow-up" } as const;

// ------------------------------------------------------------------------------ the button

export function CheckAgain({ run }: { run: Run }) {
  const router = useRouter();
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const needsLogin = run.has_test_login || run.access_mode === "account";

  async function onSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const form = new FormData(event.currentTarget);
    setBusy(true);
    setError(null);
    try {
      const response = await fetch(`/api/runs/${encodeURIComponent(run.id)}/retest`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(
          needsLogin
            ? { testEmail: String(form.get("testEmail") ?? ""), testPassword: String(form.get("testPassword") ?? "") }
            : {},
        ),
      });
      const body = (await response.json().catch(() => null)) as { id?: string; message?: string } | null;
      if (response.ok && body?.id) {
        router.push(`/run/${body.id}`);
        return;
      }
      setError(body?.message ?? "Something went wrong on our side. Please try again in a minute.");
    } catch {
      setError("Couldn't reach the server. Check your connection and try again.");
    }
    setBusy(false);
  }

  const inputClass =
    "mt-1 block w-full rounded-lg border border-line bg-surface px-3 py-2 text-base text-foreground " +
    "focus:border-accent focus:outline-none focus:ring-2 focus:ring-accent/30";

  return (
    <section className="space-y-3 rounded-xl border border-line bg-surface p-5" aria-labelledby="check-again">
      <h2 id="check-again" className="text-xl font-semibold tracking-tight">
        Check again
      </h2>
      <p className="text-sm text-muted">
        Fixed something? Run the same journey again, with the same address, goal, way in and success condition, and see
        what changed. The new visit is not told what was found before.
      </p>
      <form onSubmit={onSubmit} className="space-y-3">
        {needsLogin && (
          <fieldset className="space-y-3 rounded-lg border border-line p-3">
            <legend className="px-1 text-sm font-medium">Test account</legend>
            <p className="text-sm text-muted">
              Test logins are never kept after a run, so give one again. Use a throwaway account. Kept only until the
              check starts, never shown to the AI.
            </p>
            <div>
              <label htmlFor="retestEmail" className="text-sm font-medium">
                Test email
              </label>
              <input id="retestEmail" name="testEmail" type="email" autoComplete="off" required className={inputClass} />
            </div>
            <div>
              <label htmlFor="retestPassword" className="text-sm font-medium">
                Test password
              </label>
              <input
                id="retestPassword"
                name="testPassword"
                type="password"
                autoComplete="new-password"
                required
                className={inputClass}
              />
            </div>
          </fieldset>
        )}
        {error && (
          <p role="alert" className="text-sm text-danger">
            {error}
          </p>
        )}
        <button
          type="submit"
          disabled={busy}
          className="rounded-lg bg-accent px-5 py-2.5 font-medium text-white hover:bg-accent-strong focus:outline-none focus-visible:ring-2 focus-visible:ring-accent/40 disabled:opacity-60 dark:text-background"
        >
          {busy ? "Starting…" : "Check again"}
        </button>
      </form>
    </section>
  );
}

// ------------------------------------------------------------------------------ links between reports

// A line under the header: a re-check says which report it re-checks; a report says where its latest
// re-check is. Shown in every state of the run.
export function RetestBanner({ run, latest }: { run: Run; latest?: RunLink | null }) {
  const parts = [];
  if (run.retest_of) {
    parts.push(
      <span key="original">
        This is a check of an earlier report.{" "}
        <Link href={`/run/${run.retest_of}`} className="text-accent hover:underline">
          Open the original report
        </Link>
        .
      </span>,
    );
  }
  if (latest) {
    const state = latest.status === "done" || latest.status === "failed" ? "" : " (still running)";
    parts.push(
      <span key="latest">
        Latest check of this report:{" "}
        <Link href={`/run/${latest.id}`} className="text-accent hover:underline">
          see what changed{state}
        </Link>
        .
      </span>,
    );
  }
  if (parts.length === 0) return null;
  return (
    <p role="status" className="space-x-3 rounded-lg border border-line bg-surface p-3 text-sm text-muted">
      {parts}
    </p>
  );
}

// ------------------------------------------------------------------------------ the comparison

function VerdictSide({ title, side, href }: { title: string; side: RetestVerdictSide; href: string }) {
  return (
    <div className="space-y-1 rounded-xl border border-line bg-surface p-4">
      <p className="text-sm text-subtle">{title}</p>
      <p className="font-medium">{side ? side.headline : "No verdict"}</p>
      <p className="text-sm">
        <Link href={href} className="text-accent hover:underline">
          {title === "Before" ? "Original report" : "This report"}
        </Link>
      </p>
    </div>
  );
}

function Item({ item, originalId, thisId }: { item: RetestItem; originalId: string | null; thisId: string }) {
  return (
    <li className="space-y-2 rounded-xl border border-line bg-surface p-4">
      <div className="flex flex-wrap items-center gap-2 text-sm">
        <span className={`rounded-full px-2.5 py-0.5 font-medium ${LABEL_TONE[item.label]}`}>
          {LABEL_TEXT[item.label]}
        </span>
        {item.pass && (
          <span className="rounded-full border border-line px-2.5 py-0.5 text-muted">{PASS_TEXT[item.pass]}</span>
        )}
        <span className="rounded-full border border-line px-2.5 py-0.5 text-muted">Observed in the run</span>
      </div>
      <p className="font-medium">{item.title}</p>
      <p className="text-sm text-muted">{LABEL_MEANING[item.label]}</p>
      {item.reason && <p className="text-sm text-muted">{item.reason}</p>}
      <p className="flex flex-wrap gap-x-4 gap-y-1 text-sm">
        {originalId && item.original_step != null && (
          <Link href={`/run/${originalId}#step-${item.original_step}`} className="text-accent hover:underline">
            Original report, step {item.original_step}
            {item.original_url ? ` (${shortUrl(item.original_url)})` : ""}
          </Link>
        )}
        {item.evidence_step != null && (
          <Link href={`/run/${thisId}#step-${item.evidence_step}`} className="text-accent hover:underline">
            This report, step {item.evidence_step}
          </Link>
        )}
        {item.label === "not_reached" && <span className="text-muted">No step of this report shows it.</span>}
      </p>
    </li>
  );
}

// What changed since the original: the verdicts side by side, then every old finding labelled, then the new
// problems. Fixed always says what it means.
export function RetestComparison({ run, original }: { run: Run; original?: RunLink | null }) {
  const retest: RetestResult | null = run.retest;
  const originalId = run.retest_of ?? original?.id ?? null;
  if (!run.retest_of) return null;
  if (!retest || retest.error) {
    return (
      <section className="rounded-xl border border-line bg-surface p-4 text-sm text-muted">
        {retest?.error
          ? "The comparison with the original could not be made. The visit itself is reported below."
          : "No comparison was made for this run."}
      </section>
    );
  }
  const counts = retest.counts ?? {};
  const summary = (["fixed", "still_present", "not_reached", "inconclusive", "new"] as RetestLabel[])
    .filter((label) => (counts[label] ?? 0) > 0)
    .map((label) => `${counts[label]} ${LABEL_TEXT[label].toLowerCase()}`)
    .join(", ");
  return (
    <section className="space-y-4" aria-labelledby="what-changed">
      <div>
        <h2 id="what-changed" className="text-xl font-semibold tracking-tight">
          What changed since the original
        </h2>
        {summary && <p className="mt-1 text-sm text-muted">{summary}.</p>}
      </div>
      {retest.verdict && (
        <div className="space-y-2">
          <div className="grid gap-3 sm:grid-cols-2">
            <VerdictSide title="Before" side={retest.verdict.before} href={originalId ? `/run/${originalId}` : "#"} />
            <VerdictSide title="After" side={retest.verdict.after} href={`/run/${run.id}`} />
          </div>
          <p className="text-sm text-muted">{retest.verdict.summary}</p>
        </div>
      )}
      <ul className="space-y-3">
        {retest.labels.map((item, index) => (
          <Item key={`old-${index}`} item={item} originalId={originalId} thisId={run.id} />
        ))}
        {retest.new.map((item, index) => (
          <Item
            key={`new-${index}`}
            item={{ ...item, label: "new", pass: "independent", original_step: null }}
            originalId={originalId}
            thisId={run.id}
          />
        ))}
      </ul>
      {retest.labels.length === 0 && retest.new.length === 0 && (
        <p className="text-sm text-muted">The original report had no findings to check.</p>
      )}
      <p className="text-sm text-muted">
        <strong>Fixed</strong> means not reproduced under the tested conditions. It is not a guarantee.{" "}
        <strong>Not reached</strong> means the state was never reached, so the issue is unverified.
        {retest.guided && retest.guided.attempted > 0 && (
          <>
            {" "}
            The guided follow-up tried to follow the original route for {retest.guided.attempted} finding
            {retest.guided.attempted === 1 ? "" : "s"} and followed it for {retest.guided.followed}.
          </>
        )}
      </p>
    </section>
  );
}
"use client";

// The founder's answer to a finding: Useful, Not a real problem, or I fixed this. Saved by
// POST /api/runs/[id]/feedback; the browser remembers the visitor's vote so a reload keeps it. Kept in its
// own file so the report page changes little and the feature can be hidden by flag (lib/report-flags.ts).

import { useState } from "react";

import {
  FEEDBACK_VERDICTS,
  VERDICT_LABELS,
  readStoredVotes,
  storeVote,
  type FeedbackVerdict,
} from "@/lib/feedback-logic";

function browserStorage(): Storage | null {
  try {
    return typeof window === "undefined" ? null : window.localStorage;
  } catch {
    return null;
  }
}

type Status = "idle" | "saving" | "saved" | "failed";

export function FindingFeedback({
  runId,
  findingId,
  checkAgain,
}: {
  runId: string;
  findingId: string;
  checkAgain: boolean;
}) {
  // The report renders only after the run is fetched in the browser, so reading storage here cannot
  // differ from a server render.
  const [vote, setVote] = useState<FeedbackVerdict | null>(
    () => readStoredVotes(browserStorage(), runId)[findingId] ?? null,
  );
  const [status, setStatus] = useState<Status>("idle");

  async function send(verdict: FeedbackVerdict) {
    setStatus("saving");
    try {
      const response = await fetch(`/api/runs/${encodeURIComponent(runId)}/feedback`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ findingId, verdict }),
      });
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      setVote(verdict);
      storeVote(browserStorage(), runId, findingId, verdict);
      setStatus("saved");
    } catch {
      // The earlier vote, if any, stays selected: it is still the one the server has.
      setStatus("failed");
    }
  }

  return (
    <div className="space-y-2 border-t border-line pt-4 text-sm">
      <div className="flex flex-wrap items-center gap-2">
        <span className="text-subtle">Was this right?</span>
        <div role="group" aria-label="Your answer to this finding" className="flex flex-wrap gap-2">
          {FEEDBACK_VERDICTS.map((verdict) => {
            const chosen = vote === verdict;
            return (
              <button
                key={verdict}
                type="button"
                aria-pressed={chosen}
                disabled={status === "saving"}
                onClick={() => send(verdict)}
                className={`rounded-full border px-3 py-1 font-medium focus:outline-none focus-visible:ring-2 focus-visible:ring-accent/40 disabled:opacity-60 ${
                  chosen
                    ? "border-accent bg-accent text-white dark:text-background"
                    : "border-line bg-surface text-muted hover:border-accent hover:text-foreground"
                }`}
              >
                {VERDICT_LABELS[verdict]}
              </button>
            );
          })}
        </div>
        <span aria-live="polite" className="text-muted">
          {status === "saved" && "Thanks."}
          {status === "failed" && <span className="text-danger">Couldn&apos;t save, try again.</span>}
        </span>
      </div>
      {vote === "fixed" && checkAgain && (
        <p className="text-muted">
          <a href="#check-again" className="font-medium text-accent hover:underline">
            Check again to confirm it
          </a>
          .
        </p>
      )}
    </div>
  );
}
import type { Metadata } from "next";
import { Suspense } from "react";

import { RunView } from "./run-view";

export const metadata: Metadata = {
  title: "Visit report · First User",
  // Reports are shared by link; keep them out of search results.
  robots: { index: false, follow: false },
};

export default function RunPage({ params }: PageProps<"/run/[id]">) {
  return (
    <Suspense fallback={<p className="text-muted">Loading the run…</p>}>
      {params.then(({ id }) => (
        <RunView id={id} />
      ))}
    </Suspense>
  );
}

toolUseResult.stdout:
"use client";

// Report v2: the three answers, the verdict, the evidence labels and the run facts. Kept in its own file
// so the report page can show or hide each one by flag (lib/report-flags.ts).

import type { ReactNode } from "react";

import {
  BASIS_LABEL,
  BASIS_NOTE,
  fixFirst,
  shortUrl,
  understanding,
  withoutPromises,
} from "@/lib/report-logic";
import type { Basis, Run, RunFacts, Step, Verdict, VerdictKind } from "@/lib/types";

const BASIS_TONE: Record<Basis, string> = {
  observed: "border-line text-muted",
  verified: "border-success/30 bg-success-soft text-success",
  recommendation: "border-accent/40 text-accent",
};

// A small label saying what a statement rests on. Hidden with the labels flag.
export function BasisBadge({ basis, show = true }: { basis: Basis; show?: boolean }) {
  if (!show) return null;
  return (
    <span
      title={BASIS_NOTE[basis]}
      className={`inline-block whitespace-nowrap rounded-full border px-2 py-0.5 text-xs font-medium ${BASIS_TONE[basis]}`}
    >
      {BASIS_LABEL[basis]}
    </span>
  );
}

const VERDICT_TONE: Record<VerdictKind, string> = {
  got_through: "border-success/30 bg-success-soft",
  unconfirmed: "border-warning/30 bg-warning-soft",
  stuck: "border-danger/30 bg-danger-soft",
  login_wall: "border-warning/30 bg-warning-soft",
  bot_check: "border-warning/30 bg-warning-soft",
  our_failure: "border-line bg-surface",
};

const VERDICT_WORD: Record<VerdictKind, string> = {
  got_through: "Got through",
  unconfirmed: "Not confirmed",
  stuck: "Got stuck",
  login_wall: "Stopped at a login",
  bot_check: "Blocked by a bot check",
  our_failure: "Failed on our side",
};

const LEVEL_TONE = {
  clear: "bg-success-soft text-success",
  partly: "bg-warning-soft text-warning",
  unclear: "bg-danger-soft text-danger",
};

function Answer({ question, answer, tone, children, basis, showBasis }: {
  question: string;
  answer: string;
  tone: string;
  children?: ReactNode;
  basis: Basis;
  showBasis: boolean;
}) {
  return (
    <div className="space-y-2 rounded-xl border border-line bg-surface p-4">
      <h3 className="text-sm font-medium text-subtle">{question}</h3>
      <p>
        <span className={`rounded-full px-2.5 py-0.5 text-sm font-semibold ${tone}`}>{answer}</span>
      </p>
      <div className="space-y-1 text-sm text-muted">{children}</div>
      <BasisBadge basis={basis} show={showBasis} />
    </div>
  );
}

// Will they understand it? Can they get value? What to fix first? Answered from the first impression,
// the verdict and the top finding.
export function ThreeAnswers({ run, showBasis }: { run: Run; showBasis: boolean }) {
  const understood = understanding(run.first_impression);
  const verdict = run.verdict;
  const first = fixFirst(run.findings, verdict);
  return (
    <section aria-labelledby="three-answers" className="space-y-3">
      <h2 id="three-answers" className="text-xl font-semibold tracking-tight">
        The short answer
      </h2>
      <div className="grid gap-3 sm:grid-cols-3">
        <Answer
          question="Will a new user understand it?"
          answer={understood ? understood.label : "Not assessed"}
          tone={understood ? LEVEL_TONE[understood.level] : "bg-background text-muted"}
          basis="observed"
          showBasis={showBasis}
        >
          {understood ? (
            understood.reasons.length > 0 ? (
              <ul className="list-disc space-y-1 pl-4">
                {understood.reasons.slice(0, 3).map((reason, index) => (
                  <li key={index}>{reason}</li>
                ))}
              </ul>
            ) : (
              <p>What it does, who it is for and the main action were all clear on the landing page.</p>
            )
          ) : (
            <p>The landing page could not be reviewed.</p>
          )}
        </Answer>

        <Answer
          question="Can they get value from it?"
          answer={verdict ? VERDICT_WORD[verdict.kind] : "Not assessed"}
          tone={
            verdict
              ? verdict.kind === "got_through"
                ? LEVEL_TONE.clear
                : verdict.kind === "stuck"
                  ? LEVEL_TONE.unclear
                  : LEVEL_TONE.partly
              : "bg-background text-muted"
          }
          basis={verdict?.basis ?? "observed"}
          showBasis={showBasis}
        >
          <p>{verdict ? verdict.headline : "This run has no verdict."}</p>
        </Answer>

        <Answer
          question="What should you fix first?"
          answer={
            first.state === "finding"
              ? first.finding.title
              : first.state === "none"
                ? "Nothing stood out"
                : first.state === "not_about_site"
                  ? "Nothing, from this visit"
                  : "Not available"
          }
          tone="bg-background text-foreground"
          basis={first.state === "finding" ? "recommendation" : "observed"}
          showBasis={showBasis}
        >
          {first.state === "finding" && (
            <p>
              Ranked first of the findings below.{" "}
              <a href="#findings" className="text-accent hover:underline">
                See the finding
              </a>
              .
            </p>
          )}
          {first.state === "none" && <p>Nothing in this visit stood out as a problem with your site.</p>}
          {first.state === "not_about_site" && (
            <p>This visit says nothing about your site, so there is nothing to fix from it.</p>
          )}
        </Answer>
      </div>
      {showBasis && (
        <p className="text-xs text-subtle">
          Each answer is labelled by what it rests on. <strong>Observed</strong>: from the record of the visit.{" "}
          <strong>Verified</strong>: confirmed by an independent check. <strong>Recommendation</strong>: our
          suggestion, not a measured result.
        </p>
      )}
    </section>
  );
}

// The verdict: one headline, what it rests on, where it happened, and for a login wall the ways in.
export function VerdictCard({ verdict, run, showBasis, showSuccess }: {
  verdict: Verdict;
  run: Run;
  showBasis: boolean;
  showSuccess: boolean;
}) {
  return (
    <div className={`space-y-3 rounded-xl border p-5 ${VERDICT_TONE[verdict.kind]}`}>
      <div className="flex flex-wrap items-center gap-2">
        <p className="text-lg font-semibold">{verdict.headline}</p>
        <BasisBadge basis={verdict.basis} show={showBasis} />
      </div>
      {verdict.evidence_quote && (
        <p className="text-foreground">
          <span className="text-subtle">
            {verdict.kind === "got_through"
              ? "What confirmed it: "
              : verdict.kind === "unconfirmed"
                ? "What the check could not see: "
                : "Evidence: "}
          </span>
          {verdict.evidence_quote}
        </p>
      )}
      {verdict.detail && verdict.kind !== "unconfirmed" && <p className="text-sm text-muted">{verdict.detail}</p>}
      {(verdict.where_step !== null || verdict.where_url) && (
        <p className="text-sm text-muted">
          {verdict.where_step !== null && (
            <a href={`#step-${verdict.where_step}`} className="text-accent hover:underline">
              Step {verdict.where_step}
            </a>
          )}
          {verdict.where_step !== null && verdict.where_url ? " on " : ""}
          {verdict.where_url ? shortUrl(verdict.where_url) : ""}
        </p>
      )}
      {verdict.kind === "login_wall" && verdict.ways_in && (
        <div className="space-y-2 text-sm">
          <p className="font-medium">Three ways in</p>
          <ol className="list-decimal space-y-1 pl-5">
            {verdict.ways_in.map((way, index) => (
              <li key={index}>{way}</li>
            ))}
          </ol>
        </div>
      )}
      {showSuccess && (
        <p className="text-sm text-muted">
          {run.success_condition ? (
            <>
              <span className="text-subtle">Success condition you gave: </span>
              {run.success_condition}
            </>
          ) : (
            "The goal was checked without a stated success condition."
          )}
        </p>
      )}
      {run.reason && run.outcome !== "achieved" && (
        <p className="text-sm text-muted">
          <span className="text-subtle">The visitor&apos;s own report: </span>
          {run.reason}
        </p>
      )}
    </div>
  );
}

function fmtDuration(seconds: number): string {
  const total = Math.max(0, Math.round(seconds));
  return total < 60 ? `${total} s` : `${Math.floor(total / 60)} min ${total % 60} s`;
}

// "How this report was made", collapsed. Everything here is counted from the run, none of it is written
// by a model. The trace id is plain text.
export function RunFactsPanel({ run, steps }: { run: Run; steps: Step[] }) {
  const facts: RunFacts | null = run.run_facts;
  const cost = facts ? facts.cost_usd : Number(run.cost_usd ?? 0);
  const rows: [string, ReactNode][] = [];
  rows.push(["Steps taken", String(facts?.steps_taken ?? steps.length)]);
  if (facts) {
    rows.push([
      "Actions that needed recovery",
      facts.recoveries.length === 0
        ? "None"
        : facts.recoveries.map((r) => `step ${r.step}, rung ${r.rung} (${r.how})`).join("; "),
    ]);
    rows.push([
      "Our own issues",
      facts.own_issues.length === 0
        ? "None"
        : `${facts.own_issues.length}: ` +
          facts.own_issues.map((i) => (i.step !== null ? `step ${i.step}` : "a step")).join(", ") +
          " (our browser tool had no effect; not the site's fault)",
    ]);
    rows.push(["Page reloads", String(facts.page_reloads)]);
    rows.push([
      "Page errors recorded",
      facts.page_error_count === 0 ? "None" : (
        <ul className="list-disc space-y-1 pl-4">
          {facts.page_errors.map((error, index) => (
            <li key={index} className="break-all">
              {error}
            </li>
          ))}
          {facts.page_error_count > facts.page_errors.length && (
            <li>and {facts.page_error_count - facts.page_errors.length} more</li>
          )}
        </ul>
      ),
    ]);
    rows.push([
      "Independent check",
      facts.verifier ? `${facts.verifier.verdict}: ${facts.verifier.quote}` : "Not run (the visitor did not claim to reach the goal)",
    ]);
    rows.push([
      "Success condition",
      facts.success_condition ?? "None given: the goal was checked as worded",
    ]);
  }
  rows.push(["Cost", `$${cost.toFixed(cost < 0.1 ? 4 : 2)}`]);
  rows.push([
    "Duration",
    facts ? fmtDuration(facts.duration_seconds) : run.started_at && run.finished_at
      ? fmtDuration((Date.parse(run.finished_at) - Date.parse(run.started_at)) / 1000)
      : "—",
  ]);
  if (facts?.agent_version) rows.push(["Agent version", facts.agent_version]);
  if (facts?.worker_id) rows.push(["Worker", facts.worker_id]);
  if (facts?.trace_id) rows.push(["neatlogs trace ID", <code key="t" className="break-all">{facts.trace_id}</code>]);

  return (
    <details className="rounded-xl border border-line bg-surface p-4">
      <summary className="cursor-pointer font-medium">How this report was made</summary>
      <dl className="mt-4 space-y-3 text-sm">
        {rows.map(([label, value]) => (
          <div key={label} className="grid gap-1 sm:grid-cols-[14rem_1fr]">
            <dt className="text-subtle">{label}</dt>
            <dd className="break-words">{value}</dd>
          </div>
        ))}
      </dl>
      <p className="mt-4 text-xs text-subtle">
        The visit is a simulated user, so treat findings as leads to check. Recommendations are our suggestions and
        promise no outcome.
      </p>
    </details>
  );
}

// A recommendation as the page shows it: our wording, labelled, never promising a result.
export function Recommendation({ text, showBasis }: { text: string; showBasis: boolean }) {
  const safe = withoutPromises(text);
  if (!safe) return null;
  return (
    <span>
      {safe} <BasisBadge basis="recommendation" show={showBasis} />
    </span>
  );
}

"use client";

// Check again: the button that re-runs a finished report's journey, and the page of a re-check, which puts
// the old verdict and the new one side by side and labels each old finding. Kept in its own file so the
// report page changes little and the feature can be hidden by flag (lib/report-flags.ts).

import Link from "next/link";
import { useRouter } from "next/navigation";
import { useState, type FormEvent } from "react";

import { shortUrl } from "@/lib/report-logic";
import type { RetestItem, RetestLabel, RetestResult, RetestVerdictSide, Run, RunLink } from "@/lib/types";

const LABEL_TEXT: Record<RetestLabel, string> = {
  fixed: "Fixed",
  still_present: "Still present",
  not_reached: "Not reached",
  inconclusive: "Inconclusive",
  new: "New",
};

const LABEL_TONE: Record<RetestLabel, string> = {
  fixed: "bg-success-soft text-success",
  still_present: "bg-danger-soft text-danger",
  not_reached: "bg-warning-soft text-warning",
  inconclusive: "bg-background text-muted border border-line",
  new: "bg-danger-soft text-danger",
};

const LABEL_MEANING: Record<RetestLabel, string> = {
  fixed: "The step was reached and the original failure was not reproduced under the tested conditions.",
  still_present: "The step was reached and the failure happened again.",
  not_reached: "The state was never reached, so this is unverified. It is not reported as fixed.",
  inconclusive: "The state was reached, but the evidence does not decide it.",
  new: "A problem this check found that was not in the original report.",
};

const PASS_TEXT = { independent: "Independent visit", guided: "Guided follow-up" } as const;

// ------------------------------------------------------------------------------ the button

export function CheckAgain({ run }: { run: Run }) {
  const router = useRouter();
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const needsLogin = run.has_test_login || run.access_mode === "account";

  async function onSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const form = new FormData(event.currentTarget);
    setBusy(true);
    setError(null);
    try {
      const response = await fetch(`/api/runs/${encodeURIComponent(run.id)}/retest`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(
          needsLogin
            ? { testEmail: String(form.get("testEmail") ?? ""), testPassword: String(form.get("testPassword") ?? "") }
            : {},
        ),
      });
      const body = (await response.json().catch(() => null)) as { id?: string; message?: string } | null;
      if (response.ok && body?.id) {
        router.push(`/run/${body.id}`);
        return;
      }
      setError(body?.message ?? "Something went wrong on our side. Please try again in a minute.");
    } catch {
      setError("Couldn't reach the server. Check your connection and try again.");
    }
    setBusy(false);
  }

  const inputClass =
    "mt-1 block w-full rounded-lg border border-line bg-surface px-3 py-2 text-base text-foreground " +
    "focus:border-accent focus:outline-none focus:ring-2 focus:ring-accent/30";

  return (
    <section className="space-y-3 rounded-xl border border-line bg-surface p-5" aria-labelledby="check-again">
      <h2 id="check-again" className="text-xl font-semibold tracking-tight">
        Check again
      </h2>
      <p className="text-sm text-muted">
        Fixed something? Run the same journey again, with the same address, goal, way in and success condition, and see
        what changed. The new visit is not told what was found before.
      </p>
      <form onSubmit={onSubmit} className="space-y-3">
        {needsLogin && (
          <fieldset className="space-y-3 rounded-lg border border-line p-3">
            <legend className="px-1 text-sm font-medium">Test account</legend>
            <p className="text-sm text-muted">
              Test logins are never kept after a run, so give one again. Use a throwaway account. Kept only until the
              check starts, never shown to the AI.
            </p>
            <div>
              <label htmlFor="retestEmail" className="text-sm font-medium">
                Test email
              </label>
              <input id="retestEmail" name="testEmail" type="email" autoComplete="off" required className={inputClass} />
            </div>
            <div>
              <label htmlFor="retestPassword" className="text-sm font-medium">
                Test password
              </label>
              <input
                id="retestPassword"
                name="testPassword"
                type="password"
                autoComplete="new-password"
                required
                className={inputClass}
              />
            </div>
          </fieldset>
        )}
        {error && (
          <p role="alert" className="text-sm text-danger">
            {error}
          </p>
        )}
        <button
          type="submit"
          disabled={busy}
          className="rounded-lg bg-accent px-5 py-2.5 font-medium text-white hover:bg-accent-strong focus:outline-none focus-visible:ring-2 focus-visible:ring-accent/40 disabled:opacity-60 dark:text-background"
        >
          {busy ? "Starting…" : "Check again"}
        </button>
      </form>
    </section>
  );
}

// ------------------------------------------------------------------------------ links between reports

// A line under the header: a re-check says which report it re-checks; a report says where its latest
// re-check is. Shown in every state of the run.
export function RetestBanner({ run, latest }: { run: Run; latest?: RunLink | null }) {
  const parts = [];
  if (run.retest_of) {
    parts.push(
      <span key="original">
        This is a check of an earlier report.{" "}
        <Link href={`/run/${run.retest_of}`} className="text-accent hover:underline">
          Open the original report
        </Link>
        .
      </span>,
    );
  }
  if (latest) {
    const state = latest.status === "done" || latest.status === "failed" ? "" : " (still running)";
    parts.push(
      <span key="latest">
        Latest check of this report:{" "}
        <Link href={`/run/${latest.id}`} className="text-accent hover:underline">
          see what changed{state}
        </Link>
        .
      </span>,
    );
  }
  if (parts.length === 0) return null;
  return (
    <p role="status" className="space-x-3 rounded-lg border border-line bg-surface p-3 text-sm text-muted">
      {parts}
    </p>
  );
}

// ------------------------------------------------------------------------------ the comparison

function VerdictSide({ title, side, href }: { title: string; side: RetestVerdictSide; href: string }) {
  return (
    <div className="space-y-1 rounded-xl border border-line bg-surface p-4">
      <p className="text-sm text-subtle">{title}</p>
      <p className="font-medium">{side ? side.headline : "No verdict"}</p>
      <p className="text-sm">
        <Link href={href} className="text-accent hover:underline">
          {title === "Before" ? "Original report" : "This report"}
        </Link>
      </p>
    </div>
  );
}

function Item({ item, originalId, thisId }: { item: RetestItem; originalId: string | null; thisId: string }) {
  return (
    <li className="space-y-2 rounded-xl border border-line bg-surface p-4">
      <div className="flex flex-wrap items-center gap-2 text-sm">
        <span className={`rounded-full px-2.5 py-0.5 font-medium ${LABEL_TONE[item.label]}`}>
          {LABEL_TEXT[item.label]}
        </span>
        {item.pass && (
          <span className="rounded-full border border-line px-2.5 py-0.5 text-muted">{PASS_TEXT[item.pass]}</span>
        )}
        <span className="rounded-full border border-line px-2.5 py-0.5 text-muted">Observed in the run</span>
      </div>
      <p className="font-medium">{item.title}</p>
      <p className="text-sm text-muted">{LABEL_MEANING[item.label]}</p>
      {item.reason && <p className="text-sm text-muted">{item.reason}</p>}
      <p className="flex flex-wrap gap-x-4 gap-y-1 text-sm">
        {originalId && item.original_step != null && (
          <Link href={`/run/${originalId}#step-${item.original_step}`} className="text-accent hover:underline">
            Original report, step {item.original_step}
            {item.original_url ? ` (${shortUrl(item.original_url)})` : ""}
          </Link>
        )}
        {item.evidence_step != null && (
          <Link href={`/run/${thisId}#step-${item.evidence_step}`} className="text-accent hover:underline">
            This report, step {item.evidence_step}
          </Link>
        )}
        {item.label === "not_reached" && <span className="text-muted">No step of this report shows it.</span>}
      </p>
    </li>
  );
}

// What changed since the original: the verdicts side by side, then every old finding labelled, then the new
// problems. Fixed always says what it means.
export function RetestComparison({ run, original }: { run: Run; original?: RunLink | null }) {
  const retest: RetestResult | null = run.retest;
  const originalId = run.retest_of ?? original?.id ?? null;
  if (!run.retest_of) return null;
  if (!retest || retest.error) {
    return (
      <section className="rounded-xl border border-line bg-surface p-4 text-sm text-muted">
        {retest?.error
          ? "The comparison with the original could not be made. The visit itself is reported below."
          : "No comparison was made for this run."}
      </section>
    );
  }
  const counts = retest.counts ?? {};
  const summary = (["fixed", "still_present", "not_reached", "inconclusive", "new"] as RetestLabel[])
    .filter((label) => (counts[label] ?? 0) > 0)
    .map((label) => `${counts[label]} ${LABEL_TEXT[label].toLowerCase()}`)
    .join(", ");
  return (
    <section className="space-y-4" aria-labelledby="what-changed">
      <div>
        <h2 id="what-changed" className="text-xl font-semibold tracking-tight">
          What changed since the original
        </h2>
        {summary && <p className="mt-1 text-sm text-muted">{summary}.</p>}
      </div>
      {retest.verdict && (
        <div className="space-y-2">
          <div className="grid gap-3 sm:grid-cols-2">
            <VerdictSide title="Before" side={retest.verdict.before} href={originalId ? `/run/${originalId}` : "#"} />
            <VerdictSide title="After" side={retest.verdict.after} href={`/run/${run.id}`} />
          </div>
          <p className="text-sm text-muted">{retest.verdict.summary}</p>
        </div>
      )}
      <ul className="space-y-3">
        {retest.labels.map((item, index) => (
          <Item key={`old-${index}`} item={item} originalId={originalId} thisId={run.id} />
        ))}
        {retest.new.map((item, index) => (
          <Item
            key={`new-${index}`}
            item={{ ...item, label: "new", pass: "independent", original_step: null }}
            originalId={originalId}
            thisId={run.id}
          />
        ))}
      </ul>
      {retest.labels.length === 0 && retest.new.length === 0 && (
        <p className="text-sm text-muted">The original report had no findings to check.</p>
      )}
      <p className="text-sm text-muted">
        <strong>Fixed</strong> means not reproduced under the tested conditions. It is not a guarantee.{" "}
        <strong>Not reached</strong> means the state was never reached, so the issue is unverified.
        {retest.guided && retest.guided.attempted > 0 && (
          <>
            {" "}
            The guided follow-up tried to follow the original route for {retest.guided.attempted} finding
            {retest.guided.attempted === 1 ? "" : "s"} and followed it for {retest.guided.followed}.
          </>
        )}
      </p>
    </section>
  );
}
"use client";

// The founder's answer to a finding: Useful, Not a real problem, or I fixed this. Saved by
// POST /api/runs/[id]/feedback; the browser remembers the visitor's vote so a reload keeps it. Kept in its
// own file so the report page changes little and the feature can be hidden by flag (lib/report-flags.ts).

import { useState } from "react";

import {
  FEEDBACK_VERDICTS,
  VERDICT_LABELS,
  readStoredVotes,
  storeVote,
  type FeedbackVerdict,
} from "@/lib/feedback-logic";

function browserStorage(): Storage | null {
  try {
    return typeof window === "undefined" ? null : window.localStorage;
  } catch {
    return null;
  }
}

type Status = "idle" | "saving" | "saved" | "failed";

export function FindingFeedback({
  runId,
  findingId,
  checkAgain,
}: {
  runId: string;
  findingId: string;
  checkAgain: boolean;
}) {
  // The report renders only after the run is fetched in the browser, so reading storage here cannot
  // differ from a server render.
  const [vote, setVote] = useState<FeedbackVerdict | null>(
    () => readStoredVotes(browserStorage(), runId)[findingId] ?? null,
  );
  const [status, setStatus] = useState<Status>("idle");

  async function send(verdict: FeedbackVerdict) {
    setStatus("saving");
    try {
      const response = await fetch(`/api/runs/${encodeURIComponent(runId)}/feedback`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ findingId, verdict }),
      });
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      setVote(verdict);
      storeVote(browserStorage(), runId, findingId, verdict);
      setStatus("saved");
    } catch {
      // The earlier vote, if any, stays selected: it is still the one the server has.
      setStatus("failed");
    }
  }

  return (
    <div className="space-y-2 border-t border-line pt-4 text-sm">
      <div className="flex flex-wrap items-center gap-2">
        <span className="text-subtle">Was this right?</span>
        <div role="group" aria-label="Your answer to this finding" className="flex flex-wrap gap-2">
          {FEEDBACK_VERDICTS.map((verdict) => {
            const chosen = vote === verdict;
            return (
              <button
                key={verdict}
                type="button"
                aria-pressed={chosen}
                disabled={status === "saving"}
                onClick={() => send(verdict)}
                className={`rounded-full border px-3 py-1 font-medium focus:outline-none focus-visible:ring-2 focus-visible:ring-accent/40 disabled:opacity-60 ${
                  chosen
                    ? "border-accent bg-accent text-white dark:text-background"
                    : "border-line bg-surface text-muted hover:border-accent hover:text-foreground"
                }`}
              >
                {VERDICT_LABELS[verdict]}
              </button>
            );
          })}
        </div>
        <span aria-live="polite" className="text-muted">
          {status === "saved" && "Thanks."}
          {status === "failed" && <span className="text-danger">Couldn&apos;t save, try again.</span>}
        </span>
      </div>
      {vote === "fixed" && checkAgain && (
        <p className="text-muted">
          <a href="#check-again" className="font-medium text-accent hover:underline">
            Check again to confirm it
          </a>
          .
        </p>
      )}
    </div>
  );
}
import type { Metadata } from "next";
import { Suspense } from "react";

import { RunView } from "./run-view";

export const metadata: Metadata = {
  title: "Visit report · First User",
  // Reports are shared by link; keep them out of search results.
  robots: { index: false, follow: false },
};

export default function RunPage({ params }: PageProps<"/run/[id]">) {
  return (
    <Suspense fallback={<p className="text-muted">Loading the run…</p>}>
      {params.then(({ id }) => (
        <RunView id={id} />
      ))}
    </Suspense>
  );
}

