  /* ---------------------------------------------------------------- motion */
  --ease-out: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-spring: cubic-bezier(0.3, 1.3, 0.5, 1);
  --ease-bounce: cubic-bezier(0.3, 1.4, 0.5, 1);
  --ease-pop: cubic-bezier(0.3, 1.6, 0.5, 1);
  --ease-swipe: cubic-bezier(0.7, 0, 0.2, 1);
