  --dur-hover: 0.25s;
  --dur-card: 0.3s;
  --dur-state: 0.4s;
  --dur-slide: 0.45s;
  --dur-swipe: 0.55s;
  --dur-reveal: 0.8s;
  --dur-cursor: 1.1s;
  --dur-glow: 1.2s;
  --marquee: 42s;
}

/* ---------------------------------------------------------------- colour, dark */
@media (prefers-color-scheme: dark) {
  :root:not([data-fu-theme="light"]) {
    --bg: #0a0b0e;
    --s1: #121419;
    --s2: #17191f;
    --line: #262a32;
    --ink: #f1f2f4;
    --ink2: #c8ccd3;
    --ink3: #9da3ae;
    --ink4: #858b97;
    --off: #323843;
    --acc: #c6ff3d;
    --acc-h: #d6ff6e;
    --acc-soft: #232e10;
    --on-acc: #0e1320;
    --deep: #16181e;
    --hard: #c6ff3d;
    --blue-soft: #1a2754;
    --amber-soft: #33270e;
    --green-soft: #102b1c;
    --amber-ink: #f5c46a;
    --green-ink: #6fe3a0;
    --blue-ink: #a9bcff;
    --pass: #57e38d;
    --info: #8aa4ff;
    --bad: #ff7a6b;
    --bad-soft: #3a1714;
    --bad-ink: #ffb0a6;
    --on-bad: #0e1320;
    --warn: #f5b544;
    color-scheme: dark;
  }
}

:root[data-fu-theme="dark"] {
  --bg: #0a0b0e;
  --s1: #121419;
  --s2: #17191f;
  --line: #262a32;
  --ink: #f1f2f4;
  --ink2: #c8ccd3;
  --ink3: #9da3ae;
  --ink4: #858b97;
  --off: #323843;
  --acc: #c6ff3d;
  --acc-h: #d6ff6e;
  --acc-soft: #232e10;
  --on-acc: #0e1320;
  --deep: #16181e;
  --hard: #c6ff3d;
  --blue-soft: #1a2754;
  --amber-soft: #33270e;
  --green-soft: #102b1c;
  --amber-ink: #f5c46a;
  --green-ink: #6fe3a0;
  --blue-ink: #a9bcff;
  --pass: #57e38d;
  --info: #8aa4ff;
  --bad: #ff7a6b;
  --bad-soft: #3a1714;
  --bad-ink: #ffb0a6;
  --on-bad: #0e1320;
  --warn: #f5b544;
  color-scheme: dark;
}

/* ---------------------------------------------------------------- keyframes */
@keyframes fuBlink {
  50% {
    opacity: 0.25;
  }
}
@keyframes fuMarq {
  to {
    transform: translateX(-50%);
  }
}
@keyframes fuTap {
  0%,
  20% {
    transform: translate(70px, 46px);
  }
  45%,
  60% {
    transform: translate(0, 0);
  }
  52% {
    transform: translate(0, 0) scale(0.86);
  }
  85%,
  100% {
    transform: translate(70px, 46px);
  }
}
@keyframes fuRing {
  0%,
  45% {
    box-shadow: 0 0 0 0 rgba(201, 52, 36, 0.55);
  }
  75% {
    box-shadow: 0 0 0 12px rgba(201, 52, 36, 0);
  }
  100% {
    box-shadow: 0 0 0 0 rgba(201, 52, 36, 0);
  }
}
@keyframes fuSpin {
  to {
    transform: rotate(360deg);
  }
}
@keyframes fuNudge {
  0%,
  70%,
  100% {
    transform: translateX(0);
  }
  80% {
    transform: translateX(3px);
  }
  90% {
    transform: translateX(-1px);
  }
}
@keyframes fuPulse {
  0% {
    box-shadow: 0 0 0 0 color-mix(in srgb, var(--pass) 45%, transparent);
  }
  70% {
    box-shadow: 0 0 0 10px transparent;
  }
  100% {
    box-shadow: 0 0 0 0 transparent;
  }
}
@keyframes fuLook {
  0%,
  30% {
    transform: translateX(0);
  }
  36%,
  52% {
    transform: translateX(-6px);
  }
  58%,
  74% {
    transform: translateX(6px);
  }
  80%,
  100% {
    transform: translateX(0);
  }
}

/* Every animation and transition stops for people who ask for less motion. The scripted motion
   (reveals, the hero's demo run, counters) checks the same setting before it starts. */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation: none !important;
    transition: none !important;
    scroll-behavior: auto !important;
  }
}

