            maskImage: "radial-gradient(ellipse 55% 65% at var(--mx,70%) var(--my,45%), #000 15%, transparent 72%)",
          }}
        />
        <div
          aria-hidden
          className="absolute -z-10 rounded-full blur-[34px]"
          style={{
            left: "calc(var(--mx,72%) - min(240px,45cqi))",
            top: "calc(var(--my,40%) - min(240px,45cqi))",
            width: "min(480px,90cqi)",
            height: "min(480px,90cqi)",
            background: "radial-gradient(circle, color-mix(in srgb, var(--acc) 40%, transparent), transparent 65%)",
            transition: "left 1.2s var(--e-out), top 1.2s var(--e-out)",
          }}
        />
        <div
          className="fu-grid items-center"
          style={{
            ["--min" as string]: "460px",
            ["--gap" as string]: "64px",
            padding: "48px var(--gutter) 104px",
          }}
        >
          <div className="flex flex-col gap-7">
            <span className="fu-pill-tag">
              <span className="fu-dot-live" />
              Built at #neatHack
            </span>
            <h1 className="fu-display flex flex-col text-hero" style={{ lineHeight: 0.86, letterSpacing: "-.01em" }}>
              <span className="fu-line" style={{ paddingBottom: ".04em" }}>
                <span>Your first user.</span>
              </span>
              <span className="fu-line" style={{ padding: ".06em 0" }}>
                <span>
                  <span className="fu-mark" style={{ marginLeft: -4 }}>
                    Before
                  </span>{" "}
                  the
                </span>
              </span>
              <span className="fu-line" style={{ paddingBottom: ".04em" }}>
                <span>real ones.</span>
              </span>
            </h1>
            <p className="m-0 max-w-[500px] text-lede font-medium leading-[1.4] text-ink fu-pretty">
              Find out whether a stranger can actually use your product, before you spend money acquiring users.
            </p>
            <form
              onSubmit={(event) => go(event)}
              className="flex max-w-[540px] items-center gap-2 rounded-pill border-[1.5px] border-ink bg-s1 py-2 pl-[18px] pr-2 shadow-press"
            >
              <span aria-hidden className="font-code text-[15px] font-medium text-ink4">
                https://
              </span>
              <label htmlFor="hero-url" className="sr-only">
                Your website&apos;s address
              </label>
              <input
                id="hero-url"
                value={url}
                onChange={(event) => setHome({ url: event.target.value })}
                placeholder="your-app.com"
                inputMode="url"
                autoComplete="url"
                className="min-w-0 flex-1 border-none bg-transparent font-code text-[16px] font-medium text-ink outline-none"
              />
              <button
                type="submit"
                className="h-12 cursor-pointer whitespace-nowrap rounded-pill border-none bg-acc px-5 text-[15px] font-semibold text-on-acc transition-colors hover:bg-acc-h"
              >
                Test<span className="fu-cta-text"> my website</span> →
              </button>
            </form>
            <p className="-mt-3 ml-[18px] max-w-[480px] text-[15px] leading-normal text-ink3">
              Pick a goal next. First User opens your site and attempts it in a real browser.
            </p>
            <div className="flex flex-wrap items-center gap-x-[18px] gap-y-2.5 font-code text-[13px] font-medium text-ink3">
              <button
                type="button"
                onClick={() => setHome({ url: EXAMPLE_SITE })}
                className="h-8 cursor-pointer whitespace-nowrap rounded-pill border border-dashed border-ink3 bg-transparent px-3 font-code text-[13px] font-medium text-ink hover:border-solid hover:bg-s1"
              >
                Try {EXAMPLE_SITE}
              </button>
              <span className="flex flex-wrap items-center gap-x-[18px] gap-y-2">
                <span>A few minutes</span>
                <span aria-hidden className="size-1 rounded-full bg-ink4" />
                <span>Real browser</span>
                <span aria-hidden className="size-1 rounded-full bg-ink4" />
                <span>Watch it live</span>
              </span>
            </div>
          </div>

          <div
            onMouseMove={tilt}
            onMouseLeave={() => {
              if (cardRef.current) cardRef.current.style.transform = "";
            }}
            className="relative pb-9"
            style={{ perspective: 1200 }}
            role="img"
            aria-label="Demo: a first-time visitor creating a project on a made-up site, step by step, until the goal is reached and verified."
          >
            <div
              aria-hidden
              className="absolute -right-2 -top-[22px] z-[4] flex h-10 items-center gap-2 whitespace-nowrap rounded-pill border-[1.5px] border-ink-fixed bg-acc pl-2 pr-3.5 text-[14px] font-semibold text-on-acc"
              style={{
                boxShadow: "var(--sh-badge)",
                opacity: verified ? 1 : 0,
                transform: verified ? "none" : "translateY(8px) scale(.9)",
                transition: "opacity .4s, transform .5s var(--e-pop)",
              }}
            >
              <span className="flex size-6 items-center justify-center rounded-full bg-ink-fixed text-[13px] text-acc-fixed">
                ✓
              </span>
              Goal reached · verified
            </div>
            <div aria-hidden ref={cardRef} style={{ transition: "transform .25s ease-out", transformStyle: "preserve-3d" }}>
              <div className="overflow-hidden rounded-cardsm border-[1.5px] border-ink bg-s1 shadow-hard-xl">
                <div className="flex items-center gap-2.5 border-b border-line bg-s2 px-4 py-3">
                  <span className="fu-traffic">
                    <span />
                    <span />
                    <span />
                  </span>
                  <span className="flex h-7 min-w-0 flex-1 items-center overflow-hidden whitespace-nowrap rounded-r8 border border-line bg-s1 px-3 font-code text-[12px] font-medium text-ink3">
                    taskpond.app{h.path}
                  </span>
                  <span className="flex h-[26px] items-center gap-1.5 whitespace-nowrap rounded-pill bg-ink-fixed px-2.5 font-code text-[11px] font-medium text-acc-fixed">
                    <span className="size-1.5 rounded-full bg-acc-fixed" style={{ animation: "fuBlink 1s infinite" }} />
                    LIVE · {step + 1}
                  </span>
                </div>
                <div
                  className="relative grid h-[300px] overflow-hidden bg-page text-page-ink"
                  style={{ gridTemplateColumns: "minmax(70px,22%) minmax(0,1fr)" }}
                >
                  <div className="flex flex-col gap-2.5 border-r border-page-line bg-page-side px-3 py-4">
                    <span className="text-[13px] font-bold">Taskpond</span>
                    <span className="h-2 w-[70%] rounded bg-page-line" />
                    <span className="h-2 w-[55%] rounded bg-page-line" />
                    <span className="h-2 w-[62%] rounded bg-page-line" />
                  </div>
                  <div className="flex min-w-0 flex-col gap-3 p-[18px]">
                    <span className="h-[30px] overflow-hidden text-[20px] font-semibold leading-[1.2]">{h.title}</span>
                    {h.rows.map((row, index) => (
                      <span
                        key={index}
                        className="flex h-[34px] items-center overflow-hidden whitespace-nowrap rounded-r8 border border-page-line px-2.5 text-[13px] text-page-ink2"
                      >
                        {row}
                      </span>
                    ))}
                    <span
                      className="flex h-[34px] items-center self-start whitespace-nowrap rounded-r8 bg-page-btn px-3.5 text-[13px] font-medium text-white"
                      style={{
                        outline: `2.5px solid ${h.res === "retry" ? "#A86400" : "#0E1320"}`,
                        outlineOffset: 3,
                        transition: "outline-color .3s",
                      }}
                    >
                      {h.target}
                    </span>
                  </div>
                  <div
                    className="pointer-events-none absolute z-[2]"
                    style={{
                      left: "30%",
                      top: `${cursorY}%`,
                      transition: "left 1.1s var(--e-cursor), top 1.1s var(--e-cursor)",
                    }}
                  >
                    <svg width="22" height="22" viewBox="0 0 22 22" className="block" style={{ filter: "drop-shadow(0 2px 3px rgba(0,0,0,.25))" }}>
                      <path d="M2 2l7 18 2.6-7.4L19 10z" fill="#0E1320" stroke="#FFFFFF" strokeWidth="1.5" strokeLinejoin="round" />
                    </svg>
                    <div
                      className="absolute left-5 top-[18px] rounded-[12px_12px_12px_4px] bg-ink-fixed px-3 py-2.5 text-[13px] leading-[1.4] text-white"
                      style={{ width: "min(230px,52cqi)", boxShadow: "0 10px 24px rgba(14,19,32,.25)" }}
                    >
                      <span className="mb-[3px] block font-code text-[10px] font-medium tracking-[.06em] text-acc-fixed">
                        THINKING
                      </span>
                      {h.thought}
                    </div>
                  </div>
                </div>
                <div className="grid grid-cols-4 border-t border-line">
                  {PHASES.map((name, i) => {
                    const done = i < h.ph || h.res === "done";
                    const on = i === h.ph && !done;
                    return (
                      <div
                        key={name}
                        className="flex flex-col items-center gap-[7px] px-1.5 pb-3.5 pt-3 text-center"
                        style={{ background: on ? "var(--acc-soft)" : "var(--s1)", transition: "background .4s" }}
                      >
                        <span
                          className="flex size-5 items-center justify-center rounded-full text-[11px] font-semibold"
                          style={{
                            border: `1.5px solid ${done || on ? "var(--ink)" : "var(--off)"}`,
                            background: done ? "var(--acc)" : "var(--s1)",
                            color: done ? "#0E1320" : "var(--ink)",
                            transition: "all .4s",
                          }}
                        >
                          {done ? "✓" : i + 1}
                        </span>
                        <span className="text-[12px] font-medium leading-[1.25]" style={{ color: done || on ? "var(--ink)" : "var(--ink4)" }}>
                          {name}
                        </span>
                      </div>
                    );
                  })}
                </div>
              </div>
            </div>
            <div
              aria-hidden
              ref={feedRef}
              className="absolute -left-3 bottom-0 z-[3] flex w-[min(300px,80%)] flex-col gap-1.5 rounded-frame border-[1.5px] border-ink bg-s1 px-4 py-3.5 shadow-float"
            >
              <div className="flex items-center justify-between">
                <span className="font-code text-[11px] font-medium tracking-[.05em] text-ink3">DEMO · STEP {step + 1}</span>
                <span
                  className="flex h-[22px] items-center whitespace-nowrap rounded-pill px-[9px] text-[11px] font-semibold"
                  style={{ background: result.bg, color: result.fg }}
                >
                  {result.label}
                </span>
              </div>
              <div className="font-code text-[14px] font-medium text-ink">{h.act}</div>
            </div>
          </div>
        </div>
      </section>

      <div
        aria-hidden
        className="relative z-[2] overflow-hidden border-y-[1.5px] border-ink bg-[#0E1116] text-[#F1F2F4]"
        style={{ transform: "rotate(-1.2deg)", margin: "-10px -12px -6px" }}
      >
        <div className="flex w-max" style={{ animation: "fuMarq var(--marquee) linear infinite" }}>
          {[...MARQUEE, ...MARQUEE].map((item, index) => (
            <span
              key={index}
              className="flex items-center gap-[26px] whitespace-nowrap px-[13px] py-4 font-display text-[24px] font-[850] uppercase tracking-[.01em]"
              style={{ fontStretch: "72%" }}
            >
              {item}
              <span className="text-[18px] text-acc-fixed">✦</span>
            </span>
          ))}
        </div>
      </div>
    </>
  );
}

input.content:
"use client";

import { useRouter } from "next/navigation";
import { useEffect, useRef, useState, type FormEvent } from "react";

import type { HomeParams } from "@/lib/brief-logic";
import { FORM_ANCHOR } from "@/lib/site";
import type { ApiError } from "@/lib/types";

import { START_TEST_EVENT } from "../site-header";
import { ACCESS, LOOP, type Access } from "./data";
import { setHome, useHome, type Tab } from "./store";

type Field = "url" | "goal" | "startUrl" | "credentials" | "permission" | "success" | "form";
type FormError = { field: Field; title?: string; message: string };

const TITLES: Record<string, string> = {
  queue_full: "The queue is full",
  rate_limited: "You've reached the hourly limit",
  server_error: "Something went wrong",
};

const FIELD_OF: Record<string, Field> = {
  invalid_url: "url",
  goal_too_long: "goal",
  success_too_long: "success",
  invalid_start_url: "startUrl",
  invalid_credentials: "credentials",
  permission_required: "permission",
};

// The address field shows "https://" in front, so a filled-in https address is shown without it.
function withoutHttps(url: string): string {
  return url.replace(/^https:\/\//i, "");
}

export function StartSection({ initial }: { initial: HomeParams }) {
  const router = useRouter();
  const url = useHome((s) => s.url);
  const tab = useHome((s) => s.tab);
  const step = useHome((s) => s.step);
  const [goal, setGoal] = useState(initial.goal);
  const [success, setSuccess] = useState(initial.success);
  const [access, setAccess] = useState<Access>("public");
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<FormError | null>(null);
  const urlInput = useRef<HTMLInputElement>(null);

  // Filled in from the address (a suggested journey on a product brief, or "Run it again").
  useEffect(() => {
    const patch: { url?: string; tab: Tab } = { tab: initial.mode };
    if (initial.url) patch.url = withoutHttps(initial.url);
    setHome(patch);
  }, [initial.mode, initial.url]);

  // "Test my website" anywhere on the page lands here, on the test tab, ready to type.
  useEffect(() => {
    const focus = () => {
      setHome({ tab: "test" });
      setTimeout(() => urlInput.current?.focus({ preventScroll: true }), 300);
    };
    window.addEventListener(START_TEST_EVENT, focus);
    if (window.location.hash === `#${FORM_ANCHOR}`) focus();
    return () => window.removeEventListener(START_TEST_EVENT, focus);
  }, []);

  const testing = tab === "test";
  const accessLabel = (ACCESS.find((option) => option.id === access) ?? ACCESS[0]).t.toLowerCase();
  const next = testing
    ? [
        `Opens ${url || "your site"} in a real browser`,
        `Gets in with: ${accessLabel}`,
        `Tries to ${goal ? `"${goal.replace(/^./, (c) => c.toLowerCase())}"` : "reach the goal you write"}`,
        `An independent check confirms ${success ? `"${success}"` : "whether it got there"}`,
        "Report in a few minutes, with a fix prompt per finding",
      ]
    : [
        `Reads the public pages of ${url || "your site"}`,
        "Writes a sourced product brief",
        "Suggests 3–5 journeys you can test in one click",
      ];
  const lit = (i: number) => (i === 0 && !!url) || (i === 1 && testing) || (i === 2 && !!goal) || (i === 3 && !!success);
  const loopOn = Math.floor(step / 2) % 4;

  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const form = new FormData(event.currentTarget);
    const address = url.trim();
    if (!address) {
      setError({ field: "url", message: testing ? "Enter your app's address." : "Enter the website's address." });
      urlInput.current?.focus();
      return;
    }
    if (testing) return startTest(form, address);
    return startBrief(address);
  }

  async function startTest(form: FormData, address: string) {
    const permission = form.get("permission") === "on";
    // Only the fields of the chosen way in exist in the form, so nothing else is read or sent.
    const startUrl = access === "link" ? String(form.get("startUrl") ?? "").trim() : "";
    const testEmail = access === "account" ? String(form.get("testEmail") ?? "").trim() : "";
    const testPassword = access === "account" ? String(form.get("testPassword") ?? "") : "";
    if (access === "link" && !startUrl) {
      return setError({ field: "startUrl", message: "Enter the demo or guest link, or choose another option." });
    }
    if (access === "account" && (!testEmail || !testPassword)) {
      return setError({ field: "credentials", message: "Enter both a test email and a test password, or choose another option." });
    }
    if (!permission) {
      return setError({ field: "permission", message: "Please confirm you're allowed to test this app." });
    }
    setSubmitting(true);
    setError(null);
    try {
      const response = await fetch("/api/runs", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          url: address,
          goal: goal.trim(),
          briefId: initial.brief || undefined,
          permission,
          successCondition: success.trim() || undefined,
          access,
          startUrl: startUrl || undefined,
          testEmail: testEmail || undefined,
          testPassword: testPassword || undefined,
        }),
      });
      const body = (await response.json().catch(() => null)) as { id?: string } | ApiError | null;
      if (response.ok && body && "id" in body && body.id) {
        router.push(`/run/${body.id}`);
        return;
      }
      const apiError = body && "error" in body ? body : null;
      const code = apiError?.error ?? "server_error";
      setError({
        field: FIELD_OF[code] ?? "form",
        title: TITLES[code],
        message: apiError?.message ?? "Something went wrong on our side. Please try again in a minute.",
      });
    } catch {
      setError({ field: "form", title: "Couldn't reach the server", message: "Check your connection and try again." });
    }
    setSubmitting(false);
  }

  async function startBrief(address: string) {
    setSubmitting(true);
    setError(null);
    try {
      const response = await fetch("/api/briefs", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ url: address }),
      });
      const body = (await response.json().catch(() => null)) as { id?: string } | ApiError | null;
      if (response.ok && body && "id" in body && body.id) {
        router.push(`/brief/${body.id}`);
        return;
      }
      const apiError = body && "error" in body ? body : null;
      const code = apiError?.error ?? "server_error";
      setError({
        field: code === "invalid_url" ? "url" : "form",
        title: TITLES[code],
        message: apiError?.message ?? "Something went wrong on our side. Please try again in a minute.",
      });
    } catch {
      setError({ field: "form", title: "Couldn't reach the server", message: "Check your connection and try again." });
    }
    setSubmitting(false);
  }

  function switchTab(next: Tab) {
    setHome({ tab: next });
    setError(null);
  }

  const fieldError = (field: Field) =>
    error?.field === field ? (
      <p id={`${field}-error`} className="fu-error">
        {error.message}
      </p>
    ) : null;

  return (
    <section id="fu-start" data-reveal="" data-self="0" className="bg-s1" style={{ padding: "var(--section-y-lg) var(--gutter) var(--section-y)" }}>
      <div className="fu-grid items-start" style={{ ["--min" as string]: "420px", ["--gap" as string]: "clamp(32px,5cqi,64px)" }}>
        <div className="fu-sticky-col flex flex-col gap-6">
          <div data-stagger="">
            <span className="fu-eyebrow mb-4 block">01 · Start a run</span>
            <h2 className="fu-display text-section">
              Tell it what
              <br />
              to try.
            </h2>
          </div>
          <p data-stagger="" className="m-0 max-w-[34em] text-[18px] leading-normal text-ink2 fu-pretty">
            Test one journey now, or let it read your site first and suggest which journeys are worth testing.
          </p>
          <div data-stagger="" className="overflow-hidden rounded-cardsm border-[1.5px] border-ink bg-bg">
            <div className="flex items-center justify-between gap-2.5 border-b border-line px-4 py-3">
              <span className="fu-eyebrow">What happens next</span>
              <span className="flex items-center gap-1.5 font-code text-[12px] font-medium text-ink3">
                <span className="fu-dot-live" />
                Updates as you type
              </span>
            </div>
            <ol className="m-0 list-none py-1.5" aria-live="polite">
              {next.map((text, i) => (
                <li key={i} className="grid items-start gap-3 px-4 py-2.5" style={{ gridTemplateColumns: "28px minmax(0,1fr)" }}>
                  <span
                    className="flex size-6 items-center justify-center rounded-full border-[1.5px] border-ink text-[11px] font-semibold"
                    style={{
                      background: lit(i) ? "var(--acc)" : "var(--s1)",
                      color: lit(i) ? "#0E1320" : "var(--ink)",
                      transition: "background .4s",
                    }}
                  >
                    {i + 1}
                  </span>
                  <span className="text-[15px] leading-[1.45] text-ink [overflow-wrap:anywhere]">{text}</span>
                </li>
              ))}
            </ol>
          </div>
          <div data-stagger="" aria-hidden className="flex flex-wrap gap-2 font-code text-[13px] font-medium text-ink3">
            {LOOP.map((item, i) => {
              const on = i === loopOn;
              return (
                <span key={item.name} className="flex items-center gap-2 whitespace-nowrap">
                  <span
                    className="flex h-[30px] items-center rounded-pill px-3"
                    style={{
                      border: `1.5px solid ${on ? "var(--ink)" : "var(--line)"}`,
                      background: on ? "var(--acc)" : "var(--bg)",
                      color: on ? "var(--on-acc)" : "var(--ink)",
                      transition: "background .4s, border-color .4s",
                    }}
                  >
                    {item.name}
                  </span>
                  {i < 3 && <span>→</span>}
                </span>
              );
            })}
          </div>
        </div>

        <div id={FORM_ANCHOR} data-stagger="" className="overflow-hidden rounded-form border-[1.5px] border-ink bg-s1 shadow-hard-xl">
          <div role="tablist" aria-label="What do you want to do?" className="relative grid grid-cols-2 border-b-[1.5px] border-ink">
            <span
              aria-hidden
              className="absolute -bottom-[1.5px] z-[1] h-1 w-1/2 border-t-[1.5px] border-ink bg-acc"
              style={{ left: testing ? "0%" : "50%", transition: "left .45s var(--e-spring)" }}
            />
            {(
              [
                ["test", "Test my website"],
                ["understand", "Understand this website"],
              ] as const
            ).map(([id, label], i) => {
              const on = tab === id;
              return (
                <button
                  key={id}
                  type="button"
                  role="tab"
                  id={`tab-${id}`}
                  aria-selected={on}
                  aria-controls="fu-form-panel"
                  onClick={() => switchTab(id)}
                  className="flex min-h-14 cursor-pointer items-center justify-center gap-2 border-none px-3.5 py-2.5 text-center text-[15px] font-semibold text-ink"
                  style={{
                    background: on ? "var(--s1)" : "var(--s2)",
                    borderRight: i === 0 ? "1.5px solid var(--ink)" : "none",
                    transition: "background .3s",
                  }}
                >
                  <span className="size-2 flex-none rounded-full" style={{ background: on ? "var(--acc)" : "var(--line)" }} />
                  {label}
                </button>
              );
            })}
          </div>

          <form
            id="fu-form-panel"
            role="tabpanel"
            aria-labelledby={`tab-${tab}`}
            onSubmit={submit}
            noValidate
            className="flex flex-col gap-[18px]"
            style={{ padding: "clamp(20px,2.6cqi,28px)" }}
          >
            {initial.brief && testing && (
              <p className="fu-notice m-0">Filled in from the product brief of this site. Change anything you like before you start.</p>
            )}
            <div className="flex flex-col gap-2">
              <label htmlFor="fu-url" className="fu-label">
                <span className="fu-num">1</span>Website URL
              </label>
              <span className="fu-field-wrap" data-invalid={error?.field === "url"}>
                <span aria-hidden>https://</span>
                <input
                  ref={urlInput}
                  id="fu-url"
                  name="url"
                  inputMode="url"
                  autoComplete="url"
                  placeholder="your-app.com"
                  value={url}
                  onChange={(event) => setHome({ url: event.target.value })}
                  aria-invalid={error?.field === "url"}
