// Usage: node shoot.mjs <outDir> <width> <url> [url...]
// Opens each URL in headless Chrome at the given width, waits for it to settle, reports horizontal overflow
// (and the widest offending elements), and saves a full-page PNG.
import { spawn } from "node:child_process";
import { mkdirSync, writeFileSync, mkdtempSync } from "node:fs";
import { join } from "node:path";
import { tmpdir } from "node:os";

const [outDir, widthArg, ...urls] = process.argv.slice(2);
const width = Number(widthArg);
mkdirSync(outDir, { recursive: true });
const CHROME = "C:/Program Files/Google/Chrome/Application/chrome.exe";
const port = 9300 + Math.floor(Math.random() * 500);
const profile = mkdtempSync(join(tmpdir(), "fu-shoot-"));
const chrome = spawn(CHROME, [
  "--headless=new",
  `--remote-debugging-port=${port}`,
  `--user-data-dir=${profile}`,
  "--hide-scrollbars",
  "--no-first-run",
  `--window-size=${width},900`,
  "about:blank",
], { stdio: "ignore" });

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
let target;
for (let i = 0; i < 50; i++) {
  try {
    const list = await (await fetch(`http://127.0.0.1:${port}/json`)).json();
    target = list.find((t) => t.type === "page");
    if (target) break;
  } catch {}
  await sleep(200);
}
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((r) => ws.addEventListener("open", r, { once: true }));
let seq = 0;
const pending = new Map();
ws.addEventListener("message", (event) => {
  const msg = JSON.parse(event.data);
  if (msg.id && pending.has(msg.id)) {
    pending.get(msg.id)(msg);
    pending.delete(msg.id);
  }
});
const send = (method, params = {}) =>
  new Promise((resolve) => {
    const id = ++seq;
    pending.set(id, resolve);
    ws.send(JSON.stringify({ id, method, params }));
  });

await send("Page.enable");
await send("Runtime.enable");
const reduced = process.env.REDUCED === "1";
await send("Emulation.setEmulatedMedia", {
  features: [
    { name: "prefers-color-scheme", value: process.env.SCHEME || "dark" },
    { name: "prefers-reduced-motion", value: reduced ? "reduce" : "no-preference" },
  ],
});
await send("Emulation.setDeviceMetricsOverride", { width, height: 900, deviceScaleFactor: 1, mobile: width < 600 });

for (const url of urls) {
  await send("Page.navigate", { url });
  await sleep(Number(process.env.WAIT || 6000));
  // Scroll through so reveal animations run, then back to the top.
  await send("Runtime.evaluate", {
    expression: `(async () => { for (let y = 0; y < document.documentElement.scrollHeight; y += 600) { window.scrollTo(0, y); await new Promise(r => setTimeout(r, 120)); } window.scrollTo(0, 0); await new Promise(r => setTimeout(r, 1800)); })()`,
    awaitPromise: true,
  });
  const res = await send("Runtime.evaluate", {
    expression: `(() => {
      const vw = document.documentElement.clientWidth;
      const sw = document.documentElement.scrollWidth;
      const wide = [];
      if (sw > vw) {
        for (const el of document.querySelectorAll('body *')) {
          const r = el.getBoundingClientRect();
          if (r.right > vw + 1 && r.width > 0) {
            let p = el.parentElement, clipped = false;
            while (p) { const o = getComputedStyle(p); if (/(hidden|clip|auto|scroll)/.test(o.overflowX)) { clipped = true; break; } p = p.parentElement; }
            if (!clipped) wide.push((el.id ? '#' + el.id : el.tagName.toLowerCase()) + '.' + String(el.className).slice(0, 60) + ' right=' + Math.round(r.right));
          }
        }
      }
      return JSON.stringify({ vw, sw, h: document.documentElement.scrollHeight, title: document.title, wide: wide.slice(0, 8), errors: window.__errs || [] });
    })()`,
    returnByValue: true,
  });
  const info = JSON.parse(res.result.result.value);
  const name = url.replace(/^https?:\/\/[^/]+/, "").replace(/[^a-z0-9]+/gi, "_").slice(0, 40) || "home";
  const metrics = await send("Page.getLayoutMetrics");
  const height = Math.min(Math.ceil(metrics.result.cssContentSize.height), 16000);
  const shot = await send("Page.captureScreenshot", {
    format: "png",
    captureBeyondViewport: true,
    clip: { x: 0, y: 0, width, height, scale: 1 },
  });
  const file = join(outDir, `${name}_${width}.png`);
  writeFileSync(file, Buffer.from(shot.result.data, "base64"));
  console.log(JSON.stringify({ url, width, overflow: info.sw > info.vw, ...info, file }));
}
ws.close();
chrome.kill();

