    expression: `(() => {
      const vw = document.documentElement.clientWidth;
      const sw = document.documentElement.scrollWidth;
      const wide = [];
      if (sw > vw) {
        for (const el of document.querySelectorAll('body *')) {
          const r = el.getBoundingClientRect();
          if (r.right > vw + 1 && r.width > 0) {
            let p = el.parentElement, clipped = false;
            while (p) { const o = getComputedStyle(p); if (/(hidden|clip|auto|scroll)/.test(o.overflowX)) { clipped = true; break; } p = p.parentElement; }
            if (!clipped) wide.push((el.id ? '#' + el.id : el.tagName.toLowerCase()) + '.' + String(el.className).slice(0, 60) + ' right=' + Math.round(r.right));
          }
        }
      }
      return JSON.stringify({ vw, sw, h: document.documentElement.scrollHeight, title: document.title, wide: wide.slice(0, 8), errors: window.__errs || [] });
    })()`,
    returnByValue: true,
  });
  const info = JSON.parse(res.result.result.value);
  const name = url.replace(/^https?:\/\/[^/]+/, "").replace(/[^a-z0-9]+/gi, "_").slice(0, 40) || "home";
  const metrics = await send("Page.getLayoutMetrics");
  const height = Math.min(Math.ceil(metrics.result.cssContentSize.height), 16000);
  const shot = await send("Page.captureScreenshot", {
    format: "png",
    captureBeyondViewport: true,
    clip: { x: 0, y: 0, width, height, scale: 1 },
  });
  const file = join(outDir, `${name}_${width}.png`);
  writeFileSync(file, Buffer.from(shot.result.data, "base64"));
  console.log(JSON.stringify({ url, width, overflow: info.sw > info.vw, ...info, file }));
}
ws.close();
chrome.kill();

