const fs=require('fs'); let s=fs.readFileSync('motion.tsx','utf8');
const rep=(a,b)=>{ if(!s.includes(a)) throw new Error(a.slice(0,60)); s=s.replace(a,b); };
rep(`export function reducedMotion(): boolean {`,`// React marks a DOM node once it owns it. Until a streamed part of the page has hydrated, its HTML must stay
// exactly as the server sent it, or React reports a mismatch; such parts are scanned again shortly after.
function hydrated(el: Element): boolean {
  return Object.keys(el).some((key) => key.startsWith("__reactFiber$"));
}

export function reducedMotion(): boolean {`);
rep(`    let safety: ReturnType<typeof setTimeout> | undefined;

    function scan() {`,`    let safety: ReturnType<typeof setTimeout> | undefined;
    let retry: ReturnType<typeof setTimeout> | undefined;

    function scan() {
      let waiting = false;`);
rep(`      document.querySelectorAll<HTMLElement>(".fu-line > span").forEach((line) => {
        if (linesSeen.has(line)) return;`,`      document.querySelectorAll<HTMLElement>(".fu-line > span").forEach((line) => {
        if (linesSeen.has(line)) return;
        if (!hydrated(line)) {
          waiting = true;
          return;
        }`);
rep(`      document.querySelectorAll<HTMLElement>("[data-reveal]").forEach((el) => {
        if (seen.has(el)) return;`,`      document.querySelectorAll<HTMLElement>("[data-reveal]").forEach((el) => {
        if (seen.has(el)) return;
        if (!hydrated(el)) {
          waiting = true;
          return;
        }`);
rep(`      scrub();
      clearTimeout(safety);
      safety = setTimeout(revealVisibleLeftovers, 1500);
    }`,`      scrub();
      clearTimeout(safety);
      safety = setTimeout(revealVisibleLeftovers, 1500);
      clearTimeout(retry);
      if (waiting) retry = setTimeout(scan, 150);
    }`);
rep(`      clearTimeout(safety);
      clearTimeout(settle);`,`      clearTimeout(safety);
      clearTimeout(retry);
      clearTimeout(settle);`);
fs.writeFileSync('motion.tsx',s);
EOF
cd .. && npx tsc --noEmit -p . && echo TSOK

