"use client";

// TEMPORARY visual check of report states with fixture data. Delete before finishing.

import { readReportFlags } from "@/lib/report-flags";
import type { Run, Step, VerdictKind } from "@/lib/types";

import { RetestView } from "../run/[id]/check-again";
import { LiveRun } from "../run/[id]/live-run";
import { VerdictHero } from "../run/[id]/report-v2";

const SHOT = "https://frxdhjquvjfwgefdkcwd.supabase.co/storage/v1/object/public/screenshots/91e44505-dade-461a-8882-5a256b73b9ee/step_11.png";

function step(idx: number, tool: string, extra: Partial<Step> = {}): Step {
  return { idx, tool, thought: null, input: {}, result: { success: true, rung: "a" }, url: "https://www.saucedemo.com/inventory.html", screenshot_path: SHOT, created_at: "", ...extra };
}

const base: Run = {
  id: "x", url: "https://www.saucedemo.com/", start_url: null, has_test_login: false, access_mode: "public", first_impression: null,
  entry: null, findings: [], verdict: null, run_facts: null, success_condition: "A cart badge shows 1", retest_of: null, retest: null,
  goal: "Add a backpack to the cart", status: "done", outcome: "achieved", reason: null, cost_usd: 0.007, brain_model: null,
  created_at: "", started_at: null, finished_at: null,
};

const HEAD: Record<VerdictKind, string> = {
  got_through: "A first-time visitor got through",
  unconfirmed: "The visitor says it got through, but we could not confirm it",
  stuck: "A first-time visitor got stuck on /checkout-step-one.html",
  login_wall: "A first-time visitor was stopped at a login",
  bot_check: "The site blocked the visit with a bot check",
  our_failure: "The visit failed on our side, so this says nothing about your site",
};

export default function Preview() {
  const flags = readReportFlags("");
  const steps = [step(1, "look"), step(2, "do", { input: { instruction: "click 'Add to cart' for the backpack" } })];
  return (
    <main className="fu-page" style={{ gap: 48 }}>
      <LiveRun run={{ ...base, status: "running" }} steps={steps} />
      <LiveRun run={{ ...base, status: "queued" }} steps={[]} />
      <RetestView
        run={{
          ...base,
          retest_of: "y",
          retest: {
            labels: [
              { title: "Checkout First Name field shows 'User'", label: "fixed", pass: "independent", evidence_step: 4, original_step: 12 },
              { title: "No message when the name is too short", label: "still_present", pass: "guided", evidence_step: 6, reason: "The field still turned red with no text." },
              { title: "Pricing doesn't say if a card is needed", label: "not_reached", pass: "guided", evidence_step: null },
              { title: "'Workspace' and 'project' mean the same thing", label: "inconclusive", pass: "independent", evidence_step: 3 },
            ],
            new: [{ title: "Task order isn't saved after dragging", label: "new", evidence_step: 7 }],
            counts: { fixed: 1, still_present: 1, not_reached: 1, inconclusive: 1, new: 1 },
            verdict: {
              before: { kind: "stuck", headline: HEAD.stuck, where_step: 12, where_url: null },
              after: { kind: "got_through", headline: HEAD.got_through, where_step: null, where_url: null },
              change: "improved",
              summary: "The visitor got through this time.",
            },
          },
        }}
      />
      {(Object.keys(HEAD) as VerdictKind[]).map((kind) => (
        <VerdictHero
          key={kind}
          run={{
            ...base,
            verdict: { kind, headline: HEAD[kind], where_step: 2, where_url: "https://www.saucedemo.com/inventory.html", evidence_quote: kind === "got_through" ? "The cart badge shows 1." : "", basis: kind === "got_through" ? "verified" : "observed" },
          }}
          steps={steps}
          kind={kind}
          flags={flags}
          loginHelp={false}
        />
      ))}
    </main>
  );
}

